                ConversationTheme("lost-jumper", "The lost jumper", "Whose is it?", "tshirt", "Course", "A jumper appeared in the classroom. Help find its owner: ask what things are, whose they are and what they look like.", 1)), lessons = listOf(    Lesson(id = "en-foundations-u2-articles", title = "a/an, the & plurals", goal = "Talk about one thing, a specific thing and many things.", intro = LessonIntro(explanation = listOf("Use a or an for one of many — any one. Use an before a vowel sound: a book, an apple, an hour.", "Use the when the listener knows exactly which one. First we introduce with a/an (“I have a cat”), then we talk about it with the (“The cat is old”).", "For more than one, most words take -s: book → books. After -s, -sh, -ch, -x we add -es: bus → buses, watch → watches. A few are special: person → people, child → children."), examples = listOf(ExampleLine(text = "I have a question.", meaning = "One of many."), ExampleLine(text = "She's an artist.", meaning = "an before a vowel sound."), ExampleLine(text = "Open the window, please.", meaning = "Both people know which one."), ExampleLine(text = "I have two brothers.", meaning = "Plural with -s."), ExampleLine(text = "The buses are slow.", meaning = "Plural + the."), ExampleLine(text = "The children are at school.", meaning = "Irregular plural: child → children."))), expressions = listOf(TargetExpression(text = "a/an + thing", meaning = "One of many; an before a vowel sound.", note = "a key, an umbrella"), TargetExpression(text = "the + thing", meaning = "The one we both know.", note = "Close the door, please."), TargetExpression(text = "two/three + plural", meaning = "Most words take -s.", note = "three books, ten days"), TargetExpression(text = "-es after s/sh/ch/x", meaning = "bus → buses, watch → watches.", note = "Listen for the extra syllable."), TargetExpression(text = "people / children", meaning = "Special plurals: person → people, child → children.", note = "Never “two persons” in everyday 