    Lesson(id = "en-foundations-u3-third-person", title = "He / she / it + -s & frequency", goal = "Describe another person's routines with the -s ending and say how often things happen.", intro = LessonIntro(explanation = listOf("With he, she and it the present simple verb takes -s: “She works at night.” “He likes jazz.” This -s is small but very important.", "Questions and negatives use does: “Does she live here?” “He doesn't drive.” After does the verb loses its -s: not “Does she works?”", "Frequency words say how often: always, usually, often, sometimes, never. They go before the verb: “I always walk to work.” But after be: “He is never late.”"), examples = listOf(ExampleLine(text = "She works in a hospital.", meaning = "Third person -s."), ExampleLine(text = "He watches TV after dinner.", meaning = "-es after ch."), ExampleLine(text = "Does she speak French?", meaning = "Question with does."), ExampleLine(text = "It doesn't open on Sundays.", meaning = "Negative with doesn't."), ExampleLine(text = "I never drink energy drinks.", meaning = "never + verb."), ExampleLine(text = "He's always on time.", meaning = "Frequency after be."))), expressions = listOf(TargetExpression(text = "She + verb-s", meaning = "Third person needs -s.", note = "She plays the guitar."), TargetExpression(text = "Does he …?", meaning = "Ask about another person.", note = "Does he live alone?"), TargetExpression(text = "doesn't + verb", meaning = "He/she/it negative, no -s.", note = "It doesn't matter."), TargetExpression(text = "always / usually / sometimes / never", meaning = "How often, before the verb.", note = "I usually cook at home."), TargetExpression(text = "-es after ch/sh/s", meaning = "watches, washes, misses.", note = "She watches the news."), TargetExpression(text = "How often …?", meaning = "Ask about frequency.", note = "How often do you swim?")), situation = "You catch up about a mutual friend: describe her routines, how often she does things and what she never does.", pra