    Lesson(id = "en-foundations-u3-time", title = "Time & daily routine", goal = "Tell the time and describe your day in order.", intro = LessonIntro(explanation = listOf("Ask with “What time is it?” Answer with o'clock for exact hours: “It's seven o'clock.” For halves say half past: “It's half past seven” (7:30).", "Use at for clock times (“at eight”), in the morning/afternoon/evening, and at night.", "Order your day with first, then, after that and finally. They make a story out of your routine."), examples = listOf(ExampleLine(text = "What time is it?", meaning = "Asking the time."), ExampleLine(text = "It's half past six.", meaning = "6:30."), ExampleLine(text = "I get up at six thirty.", meaning = "at + clock time."), ExampleLine(text = "I run in the morning.", meaning = "Part of the day."), ExampleLine(text = "First I shower, then I dress.", meaning = "Order words."), ExampleLine(text = "Finally, I go to bed at eleven.", meaning = "The last step."))), expressions = listOf(TargetExpression(text = "What time is it?", meaning = "The time question.", note = "Answer: “It's …”."), TargetExpression(text = "It's … o'clock / half past …", meaning = "Exact hours and halves.", note = "It's four o'clock."), TargetExpression(text = "at + time", meaning = "Clock times take at.", note = "The film starts at nine."), TargetExpression(text = "in the morning / at night", meaning = "Parts of the day.", note = "in the evening, at night"), TargetExpression(text = "I get up at …", meaning = "Start your day.", note = "Opposite: I go to bed at …"), TargetExpression(text = "first / then / after that / finally", meaning = "Put actions in order.", note = "First coffee, then email.")), situation = "The learner's first day at a new job: plan the morning together, minute by minute, from waking up to the first meeting.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Quick — what time is it?", expected = listOf("It's <time>.", "It's half past <hour>.", "It's <hour> o'clock."), focus = "telling the time", watch = "“Is seven o'clock” — statements need it's."), PracticeQuestion(prompt = "What time do you get up?", expected = listOf("I get up at <time>."), focus = "at + time", watch = "“I get up in seven” — clock times take at."), PracticeQuestion(prompt = "Do you have breakfast before or after your shower?", expected = listOf("Before. First I …, then I …", "After — first I …"), focus = "first/then", watch = "Answer in order: first …, then …"), PracticeQuestion(prompt = "What do you do in the evening?", expected = listOf("In the evening I …", "I usually …"), focus = "in the evening", watch = "“in the night” — evening or “at night”."), PracticeQuestion(prompt = "When do you go to bed?", expected = listOf("I go to bed at <time>.", "Around <time>."), focus = "go to bed", watch = "“I go to the bed” — no the: “go to bed”."), PracticeQuestion(prompt = "Describe your morning in order — first, then, after that.", expected = listOf("First I …, then I …, after that I …"), focus = "sequencing", watch = "Use the order words — don't list with “and, and, and”."))), exercises = listOf(Exercise(id = "en-foundations-u3-time-e1", kind = "choice", prompt = "It's 7:30. It's half ___ seven.", options = listOf("past", "to", "at", "on"), answers = listOf("past"), explain = "Half past = y media."), Exercise(id = "en-foundations-u3-time-e2", kind = "gap", prompt = "I get up ___ seven o'clock.", options = listOf(), answers = listOf("at"), explain = "Clock times take at: at seven."), Exercise(id = "en-foundations-u3-time-e3", kind = "order", prompt = "Say what comes after getting up.", options = listOf(), answers = listOf("Then I have breakfast"), explain = "Then orders your routine."), Exercise(id = "en-foundations-u3-time-e4", kind = "written", prompt = "Say what time you usually get up.", options = listOf(), answers = listOf("I get up at <time>", "I usually get up at <time>"), explain = "get up at + time.")), skills = listOf("grammar:time-expressions", "vocab:daily-routine", "function:tell-time", "listening:number-time"), canDo = listOf("tell-time"), prerequisites = listOf("grammar:present-simple"))))
