    val unit = CourseUnit(id = "en-foundations-u4", title = "Getting around", subtitle = "Out in the city", level = "A1", themes = listOf(ConversationTheme("neighbourhood", "A new neighbourhood", "Find your way", "map", "Course", "The learner just moved to the area. Walk the streets together and describe what there is on every corner.", 0),
