    Lesson(id = "en-foundations-u4-there-is", title = "There is / there are", goal = "Say what exists in a place, and ask about it.", intro = LessonIntro(explanation = listOf("To say something exists, start with there: “There's a pharmacy on the corner.” Singular: there is (there's). Plural: “There are two parks.”", "Negatives: “There isn't a lift.” “There aren't any shops.” Questions: “Is there a bank near here?” “Are there any tickets left?”", "Say where with prepositions: next to, opposite, behind. “The café is next to the bank.”"), examples = listOf(ExampleLine(text = "There's a market on Saturdays.", meaning = "Singular exists."), ExampleLine(text = "There are two lifts.", meaning = "Plural exists."), ExampleLine(text = "There isn't a car park.", meaning = "Singular negative."), ExampleLine(text = "There aren't any bikes left.", meaning = "Plural negative + any."), ExampleLine(text = "Is there wifi here?", meaning = "Existence question."), ExampleLine(text = "The bank is opposite the school.", meaning = "Where exactly."))), expressions = listOf(TargetExpression(text = "There's a/n …", meaning = "One thing exists.", note = "There's a bakery downstairs."), TargetExpression(text = "There are (+ number) …", meaning = "Plural things exist.", note = "There are four rooms."), TargetExpression(text = "Is there … near here?", meaning = "Ask for a place.", note = "Is there a toilet here?"), TargetExpression(text = "There isn't / aren't any …", meaning = "What's missing.", note = "There aren't any chairs."), TargetExpression(text = "next to / opposite / behind", meaning = "Pin things to places.", note = "The bar is opposite us."), TargetExpression(text = "How many … are there?", meaning = "Ask for a number of things.", note = "How many stops are there?")), situation = "You show a visitor around the office building: what's on each floor, what's missing, and where exactly things are.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Is there a supermarket near your flat?", expected = listOf("Yes, there's one <where>.", "No, there isn't."), focus = "is there questions", watch = "“Is a supermarket?” — start with there."), PracticeQuestion(prompt = "How many rooms are there in your home?", expected = listOf("There are <number> rooms.", "There are three: …"), focus = "how many are there", watch = "“How many rooms has?” — with there: “are there”."), PracticeQuestion(prompt = "Is there a lift in the building?", expected = listOf("Yes, there is.", "No, there isn't. It's an old building."), focus = "short answers with there", watch = "“Yes, has lift” — repeat there is."), PracticeQuestion(prompt = "What's in your neighbourhood?", expected = listOf("There's a <place> and there are <things>."), focus = "mixing is/are", watch = "One thing → there's; more → there are."), PracticeQuestion(prompt = "Are there any good cafés around?", expected = listOf("Yes, there are two.", "No, there aren't any."), focus = "any in questions/negatives", watch = "“There aren't some cafés” — negatives take any."), PracticeQuestion(prompt = "Where exactly is the pharmacy?", expected = listOf("It's next to the bank.", "It's opposite the park."), focus = "location prepositions", watch = "“It's in front the bank” — “opposite” or “in front of”."))), exercises = listOf(Exercise(id = "en-foundations-u4-there-is-e1", kind = "choice", prompt = "___ a pharmacy near here?", options = listOf("Is there", "Are there", "There is", "Has"), answers = listOf("Is there"), explain = "Singular questions: Is there …?"), Exercise(id = "en-foundations-u4-there-is-e2", kind = "gap", prompt = "There ___ two parks in my neighbourhood.", options = listOf(), answers = listOf("are"), explain = "Plural things: there are."), Exercise(id = "en-foundations-u4-there-is-e3", kind = "order", prompt = "Say that a market exists on Saturdays.", options = listOf(), answers = listOf("There is a market on Saturdays"), explain = "There is + singular thing."), Exercise(id = "en-foundatio