    Lesson(id = "en-foundations-u4-directions", title = "Directions & place", goal = "Give and follow simple directions from A to B.", intro = LessonIntro(explanation = listOf("Start with go straight on, then turn left or turn right. “Go straight on and turn left at the lights.”", "Say where the place is: on the left, on the right, on the corner, at the end of the street.", "Ask for directions with “How do I get to …?” or “Is it far?” Answers: “Five minutes on foot.”"), examples = listOf(ExampleLine(text = "How do I get to the station?", meaning = "The directions question."), ExampleLine(text = "Go straight on for two streets.", meaning = "Distance first."), ExampleLine(text = "Turn right at the bank.", meaning = "Turn + where."), ExampleLine(text = "It's on the corner.", meaning = "Corner position."), ExampleLine(text = "Is it far from here?", meaning = "Ask about distance."), ExampleLine(text = "About five minutes on foot.", meaning = "Time as distance."))), expressions = listOf(TargetExpression(text = "How do I get to …?", meaning = "Ask for directions.", note = "…to the museum?"), TargetExpression(text = "Go straight on.", meaning = "Keep walking.", note = "For two blocks."), TargetExpression(text = "Turn left / right at …", meaning = "Where to change direction.", note = "at the traffic lights"), TargetExpression(text = "on the left / on the right", meaning = "Which side it's on.", note = "The pharmacy is on your left."), TargetExpression(text = "Is it far?", meaning = "Ask about distance.", note = "Answer: “Ten minutes on foot”."), TargetExpression(text = "Excuse me, …", meaning = "Open every street question.", note = "Excuse me, where's the metro?")), situation = "The learner's phone has died at a crossroads: ask passers-by for the museum, understand the directions and repeat them back.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "You look lost — can I help?", expected = listOf("Yes, please. How do I get to <place>?", "Excuse me, where is <place>?"), focus = "opening a directions ask", watch = "Start with “Excuse me” — it buys goodwill."), PracticeQuestion(prompt = "OK: go straight on and turn left at the lights. Got it?", expected = listOf("Straight on, then left at the lights.", "Got it, thanks!"), focus = "repeating directions", watch = "Repeat the route back to check it."), PracticeQuestion(prompt = "Is the museum far from here?", expected = listOf("About <number> minutes on foot.", "No, it's very close."), focus = "distance answers", watch = "“It has five minutes” — “it's five minutes”."), PracticeQuestion(prompt = "When you leave, the pharmacy is on your right.", expected = listOf("On the right. Got it.", "Thank you very much."), focus = "on the left/right", watch = "“in the right” — sides take on."), PracticeQuestion(prompt = "Where's the nearest metro station?", expected = listOf("Go straight on and it's on the corner.", "Turn right at the bank."), focus = "giving directions", watch = "Give order words: straight, then turn."), PracticeQuestion(prompt = "Perfect. One last thing — is there a toilet in the museum?", expected = listOf("Yes, there is, on the left.", "I don't know."), focus = "combining there is + location", watch = "Tie it together: there is + place word."))), exercises = listOf(Exercise(id = "en-foundations-u4-directions-e1", kind = "choice", prompt = "Go ___ and then turn left.", options = listOf("straight on", "left", "right", "back"), answers = listOf("straight on"), explain = "Straight on = todo recto."), Exercise(id = "en-foundations-u4-directions-e2", kind = "gap", prompt = "Turn left ___ the traffic lights.", options = listOf(), answers = listOf("at"), explain = "Exact points take at: at the lights."), Exercise(id = "en-foundations-u4-directions-e3", kind = "order", prompt = "Say where the bank is (beside).", options = listOf(), answers = listOf("It's next to the bank"), explain = "next to = al lado de."), Exercise(id = "en-foundations-u4-directions-e4", kind = "written", prompt = "Ask where the station is.", options = listOf(), answers = listOf("Where is the station", "Where's the station"), explain = "Question word + is: Where is / Where's.")), skills = listOf("grammar:imperatives", "grammar:prepositions-place", "vocab:directions", "function:ask-for-directions"), canDo = listOf("ask-for-directions"), prerequisites = listOf("grammar:there-is-are"))))
