object EnFoundationsNow {
    val unit = CourseUnit(id = "en-foundations-now", title = "Right now", subtitle = "What is happening", level = "A1", themes = listOf(ConversationTheme("rainy-window", "The rainy window", "Weather small talk", "cloud.rain", "Course", "You both watch the rain from a café window. Describe the weather and what people are doing outside.", 0),
                ConversationTheme("busy-kitchen", "The busy kitchen", "What is happening now", "fork.knife", "Course", "You are cooking together. Say what everyone is doing right now — and who is doing nothing!", 1)), lessons = listOf(    Lesson(id = "en-foundations-now-continuous", title = "What is happening now", goal = "Describe actions happening at this moment with am/is/are + -ing.", intro = LessonIntro(explanation = listOf("For actions happening right now, use am/is/are + verb-ing: “I am reading. She is cooking. They are playing.”", "The -ing never changes: I am eating, you are eating, he is eating. Only am/is/are changes.", "Spelling: make → making (drop the e), sit → sitting (double the consonant after one short vowel)."), examples = listOf(ExampleLine(text = "I am drinking coffee.", meaning = "An action happening now."), ExampleLine(text = "She is cooking dinner.", meaning = "Another person, is + -ing."), ExampleLine(text = "They are watching TV.", meaning = "Plural: are + -ing."), ExampleLine(text = "It's raining.", meaning = "Weather with it is + -ing."), ExampleLine(text = "He's making a cake.", meaning = "make → making: the e drops."), ExampleLine(text = "The dog is sleeping.", meaning = "Animals do things too."))), expressions = listOf(TargetExpression(text = "I'm …-ing", meaning = "What you are doing now.", note = "I'm reading a book."), TargetExpression(text = "He's / She's …-ing", meaning = "What another person is doing.", note = "She's working today."), TargetExpression(text = "They're …-ing", meaning = "What a group is doing.", note = "They're waiting for the bus."), TargetExpression(text = "It's raining / snowing", meaning = "Weather in progress.", note = "It is always it for weather."), TargetExpression(text = "… right now / at the moment", meaning = "Anchor the action to now.", note = "I'm cooking right now."), TargetExpression(text = "Look! / Listen!", meaning = "Point at an action in progress.", note = "Look! It's snowing!")), situation = "Yo