    Lesson(id = "en-foundations-now-questions", title = "Asking about now", goal = "Ask and answer present-continuous questions, and say what is not happening.", intro = LessonIntro(explanation = listOf("Questions flip the verb: “You are listening.” → “Are you listening?” “She is coming.” → “Is she coming?”", "Negatives add not: “I'm not working today.” “He isn't coming.” “They aren't sleeping.”", "Question words go first: “What are you doing?” “Where is she going?” “Who are you calling?”"), examples = listOf(ExampleLine(text = "Are you listening to me?", meaning = "A yes/no question about now."), ExampleLine(text = "Is the bus coming?", meaning = "Asking about another thing."), ExampleLine(text = "What are you doing?", meaning = "The classic question word question."), ExampleLine(text = "I'm not talking to you!", meaning = "A negative about now."), ExampleLine(text = "Where are they going?", meaning = "Question word + are."), ExampleLine(text = "No, he isn't. He's sleeping.", meaning = "Short answer, then the real action."))), expressions = listOf(TargetExpression(text = "Are you …-ing?", meaning = "Ask about the listener now.", note = "Are you coming with us?"), TargetExpression(text = "Is he/she/it …-ing?", meaning = "Ask about another person.", note = "Is the taxi coming?"), TargetExpression(text = "What are you doing?", meaning = "Ask about the current action.", note = "Nothing much — I'm reading."), TargetExpression(text = "I'm not …-ing", meaning = "Say what is not happening.", note = "I'm not eating meat this week."), TargetExpression(text = "Who is …-ing?", meaning = "Ask which person.", note = "Who is cooking tonight?"), TargetExpression(text = "Quiet! The baby's sleeping.", meaning = "Explain a stopped action.", note = "Why + negative, in one phrase.")), situation = "You phone a friend who is at a party: ask what is happening, who is doing what, and what people are not doing.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Your friend answers the phone. Ask what she is doing.", expected = listOf("What are you doing?"), focus = "what + are", watch = "“What you doing?” — informal speech drops are, but learn the full form."), PracticeQuestion(prompt = "Ask if Tom is coming to the cinema.", expected = listOf("Is Tom coming to the cinema?"), focus = "is + -ing question", watch = "“Tom is coming…?” needs a question mark of order: “Is Tom coming…?”"), PracticeQuestion(prompt = "Say you are not drinking coffee these days.", expected = listOf("I'm not drinking coffee.", "I am not drinking coffee."), focus = "negative -ing", watch = "“I no drinking” — English says “I'm not drinking”."), PracticeQuestion(prompt = "Ask where your guests are going now.", expected = listOf("Where are they going?", "Where are you going?"), focus = "where + are", watch = "“Where they going?” — keep are: “Where are they going?”"), PracticeQuestion(prompt = "Is the baby sleeping? (no)", expected = listOf("No, the baby isn't sleeping.", "No, he isn't.", "No, she isn't.", "No, it isn't."), focus = "short negative answer", watch = "“No, baby not sleeping” — “No, the baby isn't sleeping”."), PracticeQuestion(prompt = "Ask who is making that noise.", expected = listOf("Who is making that noise?", "Who's making that noise?"), focus = "who + is", watch = "“Who making” — who needs is: “Who is making…?”"))), exercises = listOf(Exercise(id = "en-foundations-now-questions-e1", kind = "choice", prompt = "___ you coming with us?", options = listOf("Are", "Is", "Do", "Does"), answers = listOf("Are"), explain = "With you, the present-continuous question starts with Are."), Exercise(id = "en-foundations-now-questions-e2", kind = "gap", prompt = "She ___ ___ working today. (negative, short form)", options = listOf(), answers = listOf("is not", "isn't"), explain = "is not → isn't: She isn't working today."), Exercise(id = "en-foundations-now-questions-e3", kind = "order", prompt = "Ask about their destination.", options = listOf(), answers = 