    Lesson(id = "en-foundations-now-weather", title = "The weather today", goal = "Talk about today's weather and what people are wearing.", intro = LessonIntro(explanation = listOf("Weather uses it: “It's cold. It's raining. It isn't sunny.” Ask: “What's the weather like?”", "Wear lives in the continuous: “I'm wearing a coat.” “She's wearing a hat.”", "Two present tenses, two jobs: habits use present simple (“It often rains here”), right now uses continuous (“It's raining now”)."), examples = listOf(ExampleLine(text = "What's the weather like?", meaning = "The standard weather question."), ExampleLine(text = "It's cold and windy.", meaning = "Weather with adjectives."), ExampleLine(text = "It's snowing again!", meaning = "A weather action in progress."), ExampleLine(text = "I'm wearing my new jacket.", meaning = "Clothes right now."), ExampleLine(text = "She's wearing a red scarf.", meaning = "Another person's clothes."), ExampleLine(text = "It often rains here, but today the sun is shining.", meaning = "Habit vs right now."))), expressions = listOf(TargetExpression(text = "What's the weather like?", meaning = "Ask about today's weather.", note = "Answer: It's + adjective."), TargetExpression(text = "It's sunny / cloudy / windy", meaning = "Weather adjectives.", note = "Adjectives, not -ing."), TargetExpression(text = "It's raining / snowing", meaning = "Weather actions in progress.", note = "-ing because it is happening now."), TargetExpression(text = "I'm wearing …", meaning = "Your clothes today.", note = "Almost always continuous."), TargetExpression(text = "Take an umbrella!", meaning = "Weather advice.", note = "Imperative — no you."), TargetExpression(text = "What a horrible day!", meaning = "React to the weather.", note = "What a + noun phrase!")), situation = "You are planning a walk with a neighbour: ask about the weather, describe what you are wearing and decide what to take.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "A neighbour opens the door. Ask about the weather.", expected = listOf("What's the weather like?"), focus = "the weather question", watch = "“How is the weather?” also works; “What's the weather like?” is the classic."), PracticeQuestion(prompt = "Describe a perfect beach day. (two adjectives)", expected = listOf("It's sunny and warm.", "It's hot and sunny."), focus = "it's + adjectives", watch = "“Is sunny” — weather needs it: “It's sunny”."), PracticeQuestion(prompt = "It started to rain. What do you say? (verb)", expected = listOf("It's raining.", "It is raining."), focus = "-ing weather", watch = "“It rains now” is a habit form; right now is “It's raining”."), PracticeQuestion(prompt = "Ask what your friend is wearing today.", expected = listOf("What are you wearing?"), focus = "wear + -ing", watch = "“What do you wear?” asks about a habit."), PracticeQuestion(prompt = "Say what you are wearing right now.", expected = listOf("I'm wearing <clothes>."), focus = "I'm wearing", watch = "“I wear a coat” sounds like every day — right now is “I'm wearing”."), PracticeQuestion(prompt = "Your friend has no coat and it's cold. Give advice.", expected = listOf("Take a coat!", "Wear a coat!", "Put on a coat!"), focus = "imperative advice", watch = "“You take a coat” is fine but the natural shout is “Take a coat!”"))), exercises = listOf(Exercise(id = "en-foundations-now-weather-e1", kind = "choice", prompt = "___ the weather like today?", options = listOf("What's", "How's", "What", "Which"), answers = listOf("What's"), explain = "The fixed question is What's the weather like?"), Exercise(id = "en-foundations-now-weather-e2", kind = "gap", prompt = "She ___ ___ a blue dress today. (wear)", options = listOf(), answers = listOf("is wearing", "'s wearing"), explain = "wear in the continuous: is wearing."), Exercise(id = "en-foundations-now-weather-e3", kind = "order", prompt = "Ask about the weather.", options = listOf(), answers = listOf("What's the weather like"), explain = "What 