object EnFoundationsDays {
    val unit = CourseUnit(id = "en-foundations-days", title = "Days & feelings", subtitle = "Your week, your health", level = "A1", themes = listOf(ConversationTheme("birthday-plan", "The birthday plan", "Which day works?", "calendar", "Course", "You are planning a small birthday dinner. Compare days, fix a date and divide the tasks.", 0),
                ConversationTheme("pharmacy-stop", "At the pharmacy", "Not feeling well", "cross.case", "Course", "You have small health problems. Say how you feel, what hurts and what you need.", 1)), lessons = listOf(    Lesson(id = "en-foundations-days-calendar", title = "Days, months & dates", goal = "Say the days of the week, months and dates, and make appointments.", intro = LessonIntro(explanation = listOf("Days and months are always capital letters: Monday, May. The week starts with Monday in the UK, Sunday in the US.", "Use on with days (on Monday), in with months and years (in June, in 2026), and at with times (at three o'clock).", "Dates: “My birthday is on 5 May” — say “the fifth of May”. Ordinals: first, second, third… twenty-first."), examples = listOf(ExampleLine(text = "The meeting is on Monday.", meaning = "on + day."), ExampleLine(text = "We're on holiday in July.", meaning = "in + month."), ExampleLine(text = "My birthday is on 5 May.", meaning = "on + date."), ExampleLine(text = "The party starts at eight.", meaning = "at + time."), ExampleLine(text = "See you on Tuesday!", meaning = "Arranging a day."), ExampleLine(text = "What day is it today?", meaning = "The daily question."))), expressions = listOf(TargetExpression(text = "What day is it today?", meaning = "Ask about the day.", note = "It's Wednesday."), TargetExpression(text = "on Monday / on Fridays", meaning = "Days with on.", note = "on Fridays = every Friday."), TargetExpression(text = "in May / in winter", meaning = "Months and seasons with in.", note = "in summer 2026"), TargetExpression(text = "at three o'clock", meaning = "Clock times with at.", note = "at half past seven"), TargetExpression(text = "My birthday is on …", meaning = "Your special date.", note = "on 12 September"), TargetExpression(text = "See you on …!", meaning = "Fix the next meeting.", note = "See you on Thursday!")), situation = "You and a classmate want to study together: compare your weeks, pick a day and a time, and put it in the calendar.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Someone asks about your routine. Say one thing you do on Mondays.", expected = listOf("On Mondays I <activity>.", "I <activity> on Mondays."), focus = "on + day", watch = "“in Monday” — days take on."), PracticeQuestion(prompt = "When is your birthday?", expected = listOf("My birthday is on <date>.", "It's on <date>."), focus = "on + date", watch = "“My birthday is 5 May” — natural English adds on."), PracticeQuestion(prompt = "Which preposition: ___ June, ___ Friday, ___ six o'clock?", expected = listOf("in June, on Friday, at six o'clock"), focus = "in / on / at", watch = "Months take in, days take on, times take at."), PracticeQuestion(prompt = "Arrange to meet a friend next weekend.", expected = listOf("See you on Saturday.", "Let's meet on Sunday."), focus = "arranging a day", watch = "“See you in Saturday” — days take on."), PracticeQuestion(prompt = "What day is it today?", expected = listOf("It's <day>.", "Today is <day>."), focus = "it + day", watch = "“Is Monday” — the answer needs it: “It's Monday”."), PracticeQuestion(prompt = "Say the month after May and the month before September.", expected = listOf("June and August"), focus = "month order", watch = "Capital letters: June, August — never june."))), exercises = listOf(Exercise(id = "en-foundations-days-calendar-e1", kind = "choice", prompt = "The course starts ___ September.", options = listOf("in", "on", "at", "to"), answers = listOf("in"), explain = "Months take in: in September."), Exercise(id = "en-foundations-days-calendar-e2", kind = "gap", prompt = "We always meet ___ Fridays.", options = listOf(), answers = listOf("on"), explain = "Days take on: on Fridays (every Friday)."), Exercise(id = "en-foundations-days-calendar-e3", kind = "order", prompt = "Say when your birthday is. (5 / on / May / My birthday / is)", options = listOf(), answers = listOf("My birthday is on 5 May"), explain = "on + day + month for dates."), Exercise(id = "en-foundations-days-calendar-e4", kind = "written", prompt = "Which is correct: “in Monday”, “on Monday” or “at Monday”?", options = listOf(), answers = listOf("on monday"), explain = "Days always take on.")), skills = listOf("grammar:time-expressions", "function:tell-time", "vocab:social-expressions"), prerequisites = listOf("grammar:time-expressions")),
    Lesson(id = "en-foundations-days-free-time", title = "Free time and hobbies", goal = "Talk about hobbies with play, go and do, and say how often.", intro = LessonIntro(explanation = listOf("Three verbs own the hobbies: play for games (play football), go for -ing activities (go swimming), do for the rest (do yoga).", "Say how often with adverbs: always, usually, often, sometimes, never — they go before the main verb: “I often swim.”", "Ask back: “What do you do in your free time?” “Do you play any sports?”"), examples = listOf(ExampleLine(text = "I play chess with my uncle.", meaning = "play + game."), ExampleLine(text = "She goes swimming on Saturdays.", meaning = "go + -ing activity."), ExampleLine(text = "We do yoga in the park.", meaning = "do + exercise."), ExampleLine(text = "I never watch TV in the morning.", meaning = "never = 0% frequency."), ExampleLine(text = "He usually plays tennis after work.", meaning = "usually + third person -s."), ExampleLine(text = "What do you do in your free time?", meaning = "The standard free-time question."))), expressions = listOf(TargetExpression(text = "What do you do in your free time?", meaning = "Ask about hobbies.", note = "Answer: I play / go / do …"), TargetExpression(text = "play + game", meaning = "Football, chess, video games.", note = "play the guitar for music."), TargetExpression(text = "go + -ing", meaning = "Swimming, running, shopping.", note = "go swimming, not go swim."), TargetExpression(text = "do + yoga / sport", meaning = "General activities.", note = "do exercise three times a week."), TargetExpression(text = "always / often / sometimes / never", meaning = "How often.", note = "Before the verb: I often read."), TargetExpression(text = "That sounds fun!", meaning = "React to a hobby.", note = "Sounds + adjective, no subject.")), situation = "You meet a neighbour at the park: ask about free time, say what you do and how often, and find one thing you both enjoy.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "A neighbour asks about your weekend. Say one hobby you do in your free time.", expected = listOf("I <play/go/do> <hobby>.", "In my free time I <activity>."), focus = "play / go / do", watch = "“I go football” — ball games take play."), PracticeQuestion(prompt = "Ask your friend about their free time.", expected = listOf("What do you do in your free time?"), focus = "the free-time question", watch = "“What you do…?” — questions need do."), PracticeQuestion(prompt = "Say how often you cook. (sometimes)", expected = listOf("I sometimes cook.", "Sometimes I cook."), focus = "frequency position", watch = "“I cook sometimes” is fine too, but “I sometimes cook” is the safest order."), PracticeQuestion(prompt = "Your friend swims every Saturday. Say it. (she)", expected = listOf("She goes swimming every Saturday.", "She swims every Saturday."), focus = "go + -ing", watch = "“She go swimming” — third person needs -s: goes."), PracticeQuestion(prompt = "React positively to a new hobby you hear about.", expected = listOf("That sounds fun!", "That's cool!", "Nice!"), focus = "reacting", watch = "“That sounds funny” means “gracioso” — fun = divertido."), PracticeQuestion(prompt = "Say one thing you never do in your free time.", expected = listOf("I never <activity>."), focus = "never + verb", watch = "“I don't never” — never is already negative."))), exercises = listOf(Exercise(id = "en-foundations-days-free-time-e1", kind = "choice", prompt = "We ___ swimming every summer.", options = listOf("go", "play", "do", "make"), answers = listOf("go"), explain = "go + -ing activity: go swimming."), Exercise(id = "en-foundations-days-free-time-e2", kind = "gap", prompt = "She ___ plays tennis after work. (usual)", options = listOf(), answers = listOf("usually"), explain = "usually goes before the main verb."), Exercise(id = "en-foundations-days-free-time-e3", kind = "order", prompt = "Ask about free time.", options = listOf(), answers = listOf("What do 