    Lesson(id = "en-foundations-days-instructions", title = "Follow the instructions", goal = "Give and follow instructions with imperatives, and politely ask people to do things.", intro = LessonIntro(explanation = listOf("The imperative is the verb alone: “Open the box. Listen carefully. Turn left.” It works for instructions, directions and recipes.", "Negatives use don't: “Don't touch it. Don't worry.”", "Soften with please and let's: “Please sit down.” “Let's start.” Let's = a suggestion for both of us."), examples = listOf(ExampleLine(text = "Open your books, please.", meaning = "A classroom instruction."), ExampleLine(text = "Turn left at the bank.", meaning = "A direction."), ExampleLine(text = "Don't touch the pan — it's hot!", meaning = "A warning."), ExampleLine(text = "Let's take a break.", meaning = "A suggestion for both."), ExampleLine(text = "Please speak slowly.", meaning = "A polite request."), ExampleLine(text = "Press this button first.", meaning = "Step-by-step help."))), expressions = listOf(TargetExpression(text = "Open / Close / Press …", meaning = "Basic instruction verbs.", note = "The verb alone is the command."), TargetExpression(text = "Don't + verb", meaning = "Stop someone politely.", note = "Don't worry."), TargetExpression(text = "Let's + verb", meaning = "Suggest doing it together.", note = "Let's go! = let us go."), TargetExpression(text = "…, please.", meaning = "The softener.", note = "Please can go first too: Please sit down."), TargetExpression(text = "First …, then …", meaning = "Order the steps.", note = "First press, then wait."), TargetExpression(text = "Careful!", meaning = "A short warning.", note = "= Be careful!")), situation = "You help a friend use a new coffee machine: give the steps in order, warn about the hot part and suggest trying it together.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "The class is noisy. What does the teacher say? (quiet)", expected = listOf("Be quiet!", "Quiet, please.", "Please be quiet."), focus = "be imperative", watch = "“You be quiet” is possible but the clean imperative is “Be quiet”."), PracticeQuestion(prompt = "Warn your friend about the hot pan.", expected = listOf("Don't touch the pan!", "Careful, it's hot!"), focus = "don't + verb", watch = "“Not touch” — the negative imperative needs don't."), PracticeQuestion(prompt = "Suggest starting the exercise together.", expected = listOf("Let's start the exercise.", "Let's begin."), focus = "let's + verb", watch = "“Let's to start” — let's takes the bare verb."), PracticeQuestion(prompt = "Give the first two steps for the machine.", expected = listOf("First press the button, then wait.", "Press this button, then wait."), focus = "first / then", watch = "Instructions follow order words: first, then, after that."), PracticeQuestion(prompt = "Ask someone to speak more slowly, politely.", expected = listOf("Please speak slowly.", "Speak slowly, please.", "Could you speak slowly?"), focus = "polite request", watch = "“Speak slow” — the adverb is slowly."), PracticeQuestion(prompt = "Tell your friend not to worry about the mistake.", expected = listOf("Don't worry!", "Don't worry about it."), focus = "don't worry", watch = "“No worry” is not English — “Don't worry”."))), exercises = listOf(Exercise(id = "en-foundations-days-instructions-e1", kind = "choice", prompt = "___ worry — it's easy!", options = listOf("Don't", "Not", "No", "Doesn't"), answers = listOf("Don't"), explain = "The negative imperative is Don't + verb."), Exercise(id = "en-foundations-days-instructions-e2", kind = "gap", prompt = "___ start with question one. (suggestion for both)", options = listOf(), answers = listOf("let's", "lets", "let us"), explain = "Let's = a suggestion for both of us."), Exercise(id = "en-foundations-days-instructions-e3", kind = "order", prompt = "Politely ask for quiet.", options = listOf(), answers = listOf("Please be quiet"), explain = "Be + adjective works in imperatives."), Exercise(id = "en-foundations-days-instructions-e4", kind = "written", prompt = "Put in order: press / first / this button / .", options = listOf(), answers = listOf("press this button first", "first press this button"), explain = "first can go before or after the instruction.")), skills = listOf("grammar:imperatives", "function:make-requests", "vocab:social-expressions"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-foundations-days-feelings", title = "How do you feel?", goal = "Describe feelings and small health problems, and ask about other people.", intro = LessonIntro(explanation = listOf("Feelings use be: “I'm tired. She's happy. They're hungry.” Health problems use have got: “I've got a headache.”", "Ask: “How are you feeling?” “What's wrong?” Answer: “I don't feel well.” “My leg hurts.”", "Small comfort: “Get better soon!” “Take care!”"), examples = listOf(ExampleLine(text = "I'm so tired today.", meaning = "A feeling with be."), ExampleLine(text = "I've got a headache.", meaning = "A health problem with have got."), ExampleLine(text = "My back hurts.", meaning = "A body part + hurts."), ExampleLine(text = "What's wrong?", meaning = "Ask about a problem."), ExampleLine(text = "She isn't feeling well.", meaning = "Feeling ill, continuous."), ExampleLine(text = "Get better soon!", meaning = "A warm goodbye to someone ill."))), expressions = listOf(TargetExpression(text = "I'm tired / hungry / happy", meaning = "Feelings with be.", note = "Never “I have tired”."), TargetExpression(text = "I've got a headache / a cold", meaning = "Small health problems.", note = "have got + a + illness."), TargetExpression(text = "My … hurts.", meaning = "Point at the pain.", note = "My throat hurts."), TargetExpression(text = "What's wrong?", meaning = "Notice someone's problem.", note = "= What's the matter?"), TargetExpression(text = "I don't feel well.", meaning = "The general “me siento mal”.", note = "well = fine, here."), TargetExpression(text = "Get better soon! / Take care!", meaning = "Warm wishes.", note = "Fixed phrases.")), situation = "A colleague looks pale at work: ask what is wrong, they describe small problems, and you comfort them and give simple advice.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Your friend looks sad. Ask what's wrong.", expected = listOf("What's wrong?", "What's the matter?"), focus = "noticing", watch = "“What you have?” — the fixed question is “What's wrong?”"), PracticeQuestion(prompt = "Say you have a pain in your head.", expected = listOf("I've got a headache.", "I have a headache.", "My head hurts."), focus = "have got + illness", watch = "“I have headache” — the article matters: “a headache”."), PracticeQuestion(prompt = "Say how you feel today. (tired)", expected = listOf("I'm tired.", "I'm very tired today."), focus = "be + feeling", watch = "“I have tired” — feelings take be."), PracticeQuestion(prompt = "Your colleague says she doesn't feel well. Comfort her.", expected = listOf("Get better soon!", "Take care!", "Go home and rest."), focus = "comforting", watch = "Any warm fixed phrase works here."), PracticeQuestion(prompt = "Ask about your friend's back pain today.", expected = listOf("How is your back today?", "Is your back better?", "Does your back still hurt?"), focus = "asking about pain", watch = "“How is your back?” is the natural follow-up."), PracticeQuestion(prompt = "Say two things you need when you have a cold.", expected = listOf("I need water and rest.", "I need tea and tissues."), focus = "need + noun", watch = "need + noun for things, need + to + verb for actions."))), exercises = listOf(Exercise(id = "en-foundations-days-feelings-e1", kind = "choice", prompt = "I ___ so tired today.", options = listOf("'m", "have", "am having", "do"), answers = listOf("'m"), explain = "Feelings take be: I'm tired."), Exercise(id = "en-foundations-days-feelings-e2", kind = "gap", prompt = "I've ___ a terrible headache.", options = listOf(), answers = listOf("got", "get"), explain = "have got a headache — got completes the pair."), Exercise(id = "en-foundations-days-feelings-e3", kind = "order", prompt = "Ask about a problem you notice.", options = listOf(), answers = listOf("What is wrong"), explain = "The fixed question: What's wrong?"), Exercise(id = "en-foundations-days-feelings-e4", kind = "written", prompt = "Your throat hurts. Say it two ways.", options = listOf(), answers = listOf("my throat hurts", "i've got a sore throat", "i have a sore throat", "my throat is sore"), explain = "My X hurts or I've got a sore throat.")), skills = listOf("vocab:feelings", "vocab:health", "function:talk-about-health", "grammar:have-got"), prerequisites = listOf("grammar:have-got", "grammar:verb-be"))))
}

object EnFoundationsTransport {
