king?", expected = listOf("Yes, I do.", "No, I don't. I hate cooking."), focus = "like questions", watch = "“Do you like cook?” — verb+ing after like."), PracticeQuestion(prompt = "What's something you hate doing?", expected = listOf("I hate <verb>ing."), focus = "hate + -ing", watch = "“I hate get up” — “hate getting up”."), PracticeQuestion(prompt = "Do you mind waiting?", expected = listOf("No, I don't mind waiting.", "Yes, I hate waiting."), focus = "don't mind", watch = "“I don't mind wait” — keep -ing."), PracticeQuestion(prompt = "How much do you like films — a bit or a lot?", expected = listOf("I really like films.", "I quite like them."), focus = "softeners", watch = "“I like very much films” — “I really like films”."), PracticeQuestion(prompt = "Your friend loves dancing but you don't. What do you say?", expected = listOf("I don't really like dancing.", "I don't like dancing, but thanks!"), focus = "polite dislike", watch = "Soften with really: “I don't really like…”."))), exercises = listOf(Exercise(id = "en-foundations-u5-likes-e1", kind = "choice", prompt = "I love ___ to music.", options = listOf("listening", "listen", "listens", "to listening"), answers = listOf("listening"), explain = "Like/love/hate + verb-ing."), Exercise(id = "en-foundations-u5-likes-e2", kind = "gap", prompt = "She hates ___ up early. (get)", options = listOf(), answers = listOf("getting"), explain = "Short verb + consonant doubles: get → getting."), Exercise(id = "en-foundations-u5-likes-e3", kind = "order", prompt = "Ask if the person enjoys cooking.", options = listOf(), answers = listOf("Do you like cooking"), explain = "Do you like + -ing?"), Exercise(id = "en-foundations-u5-likes-e4", kind = "written", prompt = "Say one thing you love doing.", options = listOf(), answers = listOf("I love <verbing>", "I love <verb>ing"), explain = "I love + activity with -ing.")), skills = listOf("grammar:gerunds-infinitives", "vocab:hobbies", "function:express-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-foundations-u5-cafe", title = "Ordering at a café", goal = "Order food and drink, ask for things and pay, in real café English.", intro = LessonIntro(explanation = listOf("The magic order phrase is “I'd like …” (I would like) — polite and universal. “Can I have …, please?” works everywhere too.", "The server asks: “Anything else?” Answer: “That's all, thanks.” Pay with: “The bill, please.”", "Choices come fast: “Large or small?” “For here or to go?” Answer with a full mini-sentence: “Small, to go, please.”"), examples = listOf(ExampleLine(text = "I'd like a cappuccino, please.", meaning = "The polite order."), ExampleLine(text = "Can I have a glass of water?", meaning = "Alternative order."), ExampleLine(text = "Anything else?", meaning = "The server asks for more."), ExampleLine(text = "That's all, thanks.", meaning = "Close the order."), ExampleLine(text = "For here or to go?", meaning = "The classic choice."), ExampleLine(text = "Can I have the bill, please?", meaning = "Ask to pay."))), expressions = listOf(TargetExpression(text = "I'd like …, please.", meaning = "Polite order — would like.", note = "I'd like the soup."), TargetExpression(text = "Can I have …, please?", meaning = "Order or ask for anything.", note = "Can I have a spoon?"), TargetExpression(text = "Anything else?", meaning = "Server asks for more.", note = "Answer: “No, that's all”."), TargetExpression(text = "For here or to go?", meaning = "Eat in or take away.", note = "To go, please."), TargetExpression(text = "The bill, please.", meaning = "Ask to pay.", note = "Also: “Could we pay, please?”"), TargetExpression(text = "Keep the change.", meaning = "Generous close.", note = "Small tip, big smile.")), situation = "A busy café at breakfast time: order for you and the learner, handle the server's questions and settle the bill.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Good morning! What can I get you?", expected = listOf("I'd like a <drink>, please.", "Can I have a <drink>, please?"), focus = "opening an order", watch = "“I want a coffee” — understandable, but “I'd like” is politer."), PracticeQuestion(prompt = "Anything else?", expected = listOf("That's all, thanks.", "Yes, also a <item>, please."), focus = "closing the order", watch = "“Nothing more” — natural is “That's all, thanks”."), PracticeQuestion(prompt = "For here or to go?", expected = listOf("For here, please.", "To go, please."), focus = "the classic choice", watch = "Answer the part they asked: here/to go."), PracticeQuestion(prompt = "Large or small?", expected = listOf("Large, please.", "Small is fine."), focus = "size answers", watch = "“I take large” — “Large, please” is the café norm."), PracticeQuestion(prompt = "Here you are — anything else for you two?", expected = listOf("Yes — the bill, please.", "No, thanks. Keep the change."), focus = "paying phrases", watch = "“Give me the bill” — “The bill, please” is polite."), PracticeQuestion(prompt = "How was everything?", expected = listOf("Delicious, thank you!", "Very good, thanks."), focus = "polite close", watch = "One warm sentence closes the visit."))), exercises = listOf(Exercise(id = "en-foundations-u5-cafe-e1", kind = "choice", prompt = "___ like a coffee, please.", options = listOf("I'd", "I", "Me", "Mine"), answers = listOf("I'd"), explain = "I'd like = polite want."), Exercise(id = "en-foundations-u5-cafe-e2", kind = "gap", prompt = "Can I have the ___ , please? (la cuenta)", options = listOf(), answers = listOf("bill"), explain = "The bill (UK) / the check (US)."), Exercise(id = "en-foundations-u5-cafe-e3", kind = "order", prompt = "Ask for the menu politely.", options = listOf(), answers = listOf("Can I have the menu, please"), explain = "Can I have … , please? works everywhere."), Exercise(id = "en-foundations-u5-cafe-e4", kind = "written", prompt = "Order a tea politely.", options = listOf(), answers = listOf("Can I have a tea, please", "I'd like a tea, please", "Can I have