    val unit = CourseUnit(id = "en-foundations-u6", title = "The past begins", subtitle = "Tell what happened", level = "A2", themes = listOf(ConversationTheme("weekend", "The weekend", "What happened", "sun.max", "Course", "Monday catch-up: tell each other what you really did at the weekend, moment by moment.", 0),
                ConversationTheme("last-trip", "A trip to remember", "Tell the story", "airplane", "Course", "You swap stories of a memorable trip: where you were, what you did and how it ended.", 1)), lessons = listOf(    Lesson(id = "en-foundations-u6-was-were", title = "Was / were", goal = "Describe people, places and feelings in the past with was and were.", intro = LessonIntro(explanation = listOf("Was and were are the past of to be. I/he/she/it → was. You/we/they → were. “I was at home.” “They were at the beach.”", "Negatives: wasn't, weren't. Questions flip: “Was it good?” “Where were you?”", "Anchor the story in time: yesterday, last night, last week, in 2020, this morning."), examples = listOf(ExampleLine(text = "I was tired yesterday.", meaning = "was with I."), ExampleLine(text = "The film was great.", meaning = "was with it."), ExampleLine(text = "We were at Ana's party.", meaning = "were with we."), ExampleLine(text = "The streets weren't empty.", meaning = "Plural negative."), ExampleLine(text = "Was the weather good?", meaning = "Past question."), ExampleLine(text = "Where were you last night?", meaning = "Question word + were."))), expressions = listOf(TargetExpression(text = "I was / he was …", meaning = "Past of be, singular.", note = "She was delighted."), TargetExpression(text = "you were / they were", meaning = "Past of be, plural.", note = "They were neighbours."), TargetExpression(text = "wasn't / weren't", meaning = "Past negatives.", note = "It wasn't my fault."), TargetExpression(text = "Was it …? / Were you …?", meaning = "Past yes/no questions.", note = "Was it far?"), TargetExpression(text = "yesterday / last night / last week", meaning = "Anchor the story in time.", note = "last weekend"), TargetExpression(text = "It was amazing / awful.", meaning = "Give your verdict of the past.", note = "The concert? It was amazing.")), situation = "You bump into a friend who missed the neighbourhood party on Saturday: recount who was there, how it w