    Lesson(id = "en-foundations-u6-past", title = "Past simple: -ed", goal = "Tell what you and others did, with regular past forms and didn't.", intro = LessonIntro(explanation = listOf("For finished actions, regular verbs add -ed: work → worked, play → played, watch → watched. The same form works for every person.", "Questions and negatives use did + plain verb: “Did you walk?” “I didn't walk.” After did, no -ed: not “Did you walked?”", "Spelling: love → loved (no e), study → studied (y→ied), stop → stopped (double p)."), examples = listOf(ExampleLine(text = "I worked late yesterday.", meaning = "-ed, all persons."), ExampleLine(text = "She played tennis on Saturday.", meaning = "Same -ed with she."), ExampleLine(text = "Did you watch the match?", meaning = "did + plain verb."), ExampleLine(text = "We didn't stay long.", meaning = "didn't + plain verb."), ExampleLine(text = "They studied all night.", meaning = "y → ied."), ExampleLine(text = "It stopped suddenly.", meaning = "Double consonant."))), expressions = listOf(TargetExpression(text = "verb + -ed", meaning = "Regular past, every person.", note = "I called you twice."), TargetExpression(text = "Did you …?", meaning = "Past question, plain verb.", note = "Did you enjoy it?"), TargetExpression(text = "I didn't …", meaning = "Past negative, plain verb.", note = "I didn't sleep well."), TargetExpression(text = "Yes, I did. / No, I didn't.", meaning = "Short answers.", note = "Repeat did."), TargetExpression(text = "y → ied", meaning = "study → studied, try → tried.", note = "We tried the new café."), TargetExpression(text = "yesterday evening / last Friday", meaning = "Past time anchors.", note = "last Friday night")), situation = "You compare diaries from a chaotic Tuesday: what you did, what you didn't do, and what the other did first.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "What did you do yesterday evening?", expected = listOf("I <verb>ed …", "I watched TV and cooked dinner