    Lesson(id = "en-foundations-u6-weekend", title = "Your weekend (repaso)", goal = "Tell the story of your weekend in order — past be, past verbs, time anchors — and ask about someone else's.", intro = LessonIntro(explanation = listOf("A weekend story has three parts: where you were (was/were), what you did (past -ed), and how it was (was + opinion).", "Order it with time anchors: on Saturday morning, then, in the evening, later, finally.", "Keep the conversation alive: ask back with “What about you?” or “Did you …?”"), examples = listOf(ExampleLine(text = "On Friday I was at home — I was exhausted.", meaning = "Part 1: where + how."), ExampleLine(text = "On Saturday I visited my parents.", meaning = "Part 2: past action."), ExampleLine(text = "We walked in the park and talked for hours.", meaning = "Two past verbs, one story."), ExampleLine(text = "In the evening I watched a film.", meaning = "Time anchor + past."), ExampleLine(text = "It was a really good weekend.", meaning = "Part 3: the verdict."), ExampleLine(text = "What about you? What did you do?", meaning = "Ask it back."))), expressions = listOf(TargetExpression(text = "On Saturday morning, …", meaning = "Open the story with a time.", note = "…I played padel."), TargetExpression(text = "First …, then …, later …", meaning = "Sequence the actions.", note = "Then we had lunch."), TargetExpression(text = "I visited / called / watched …", meaning = "Regular past actions.", note = "I called my brother."), TargetExpression(text = "It was really + adjective", meaning = "Give your verdict.", note = "It was really relaxing."), TargetExpression(text = "What about you?", meaning = "Return the question.", note = "The conversation keeps flowing."), TargetExpression(text = "That sounds + adjective", meaning = "React to the other's story.", note = "That sounds fun!")), situation = "Monday coffee with a friend: take turns telling your weekends, react, and ask at least two questions back.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "So — how was your weekend?", expected = listOf("It was <adjective>. On Saturday I …", "Really good, thanks!"), focus = "verdict + story opener", watch = "Start with the verdict, then the story."), PracticeQuestion(prompt = "What did you do on Saturday?", expected = listOf("I <verb>ed … First …, then …"), focus = "past actions in order", watch = "Use -ed for regular verbs and an order word."), PracticeQuestion(prompt = "Were you with friends or alone?", expected = listOf("I was with <people>.", "I was on my own."), focus = "was/were recap", watch = "“I was with” — was works with I."), PracticeQuestion(prompt = "That sounds nice! Did you eat out?", expected = listOf("Yes, we did — we tried a new place.", "No, we didn't. We cooked at home."), focus = "did questions about the story", watch = "“Yes, we eat out” — past short answer: “Yes, we did”."), PracticeQuestion(prompt = "What about Sunday?", expected = listOf("On Sunday I …", "Sunday was quieter — I …"), focus = "extending the story", watch = "Another time anchor, another scene."), PracticeQuestion(prompt = "OK, your turn — ask me about my weekend.", expected = listOf("What did you do?", "How was your weekend?"), focus = "asking back", watch = "A conversation needs a return serve: ask one question."))), exercises = listOf(Exercise(id = "en-foundations-u6-weekend-e1", kind = "choice", prompt = "___ you have a good weekend?", options = listOf("Did", "Was", "Were", "Do"), answers = listOf("Did"), explain = "have is a normal verb: questions need Did."), Exercise(id = "en-foundations-u6-weekend-e2", kind = "gap", prompt = "We ___ so tired on Sunday.", options = listOf(), answers = listOf("were"), explain = "Past be with we: were."), Exercise(id = "en-foundations-u6-weekend-e3", kind = "order", prompt = "Start your Saturday story.", options = listOf(), answers = listOf("On Saturday I met my friends"), explain = "Time anchor first: On Saturday …"), Exercise(id = "en-foundations-u6-weekend-e4", kind = "written", prompt = "Tell one thing you did last weekend.", options = listOf(), answers = listOf("I <verbed> last weekend", "Last weekend I <verbed>", "On Saturday I <verbed>"), explain = "Past verb + time anchor.")), skills = listOf("grammar:past-simple-irregular", "grammar:time-expressions", "function:tell-a-story", "speaking:tell-past-story"), canDo = listOf("tell-a-story"), prerequisites = listOf("grammar:past-simple-regular"))))
