    val unit = CourseUnit(id = "en-foundations-compare", title = "Comparing & choosing", subtitle = "Which one is better?", level = "A2", themes = listOf(ConversationTheme("two-flats", "Two flats, one choice", "Compare and decide", "house", "Course", "You visit two flats to rent. Compare rooms, price, light and noise — then choose one together.", 0),
