tives take more: more comfortable."), Exercise(id = "en-foundations-compare-comparatives-e2", kind = "gap", prompt = "My city is ___ (big) than yours.", options = listOf(), answers = listOf("bigger"), explain = "big → bigger: double the g."), Exercise(id = "en-foundations-compare-comparatives-e3", kind = "order", prompt = "Say the train is faster.", options = listOf(), answers = listOf("The train is faster than the bus"), explain = "comparative + than."), Exercise(id = "en-foundations-compare-comparatives-e4", kind = "written", prompt = "Fix the mistake: “This film is more good than the book.”", options = listOf(), answers = listOf("this film is better than the book"), explain = "good → better — the irregular wins.")), skills = listOf("grammar:comparatives", "grammar:articles", "function:express-opinion", "speaking:justify-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:articles", "grammar:verb-be")),
    Lesson(id = "en-foundations-compare-superlatives", title = "Superlatives", goal = "Say which one is the most / the -est in a group.", intro = LessonIntro(explanation = listOf("Short adjectives: the + -est: the cheapest, the biggest, the busiest. Long adjectives: the most + adjective: the most beautiful.", "Superlatives live with in or of: “the cheapest café in town”, “the best day of the year”.", "Irregulars: good → the best, bad → the worst."), examples = listOf(ExampleLine(text = "It's the cheapest café in town.", meaning = "the + -est + in + place."), ExampleLine(text = "That's the most beautiful street here.", meaning = "the most + long adjective."), ExampleLine(text = "August is the busiest month.", meaning = "busy → the busiest."), ExampleLine(text = "This is the best pizza in the city!", meaning = "Irregular: the best."), ExampleLine(text = "Monday was the worst day of the week.", meaning = "the worst + of + group."), ExampleLine(text = "It's the oldest building in the neighbourhood.", meaning = "old → the oldest."))), expressions = listOf(TargetExpression(text = "the … -est in/of …", meaning = "Top of a short-adjective group.", note = "the oldest in the family."), TargetExpression(text = "the most … in/of …", meaning = "Top of a long-adjective group.", note = "the most famous in Spain."), TargetExpression(text = "the best / the worst", meaning = "The two irregular tops.", note = "the best day ever."), TargetExpression(text = "my favourite …", meaning = "Your personal top one.", note = "my favourite café in town."), TargetExpression(text = "What's the best … ?", meaning = "Ask for a recommendation.", note = "What's the best way to get there?"), TargetExpression(text = "one of the … -est", meaning = "Near the top, not the very top.", note = "one of the oldest bars in Madrid.")), situation = "A tourist asks you about your town: recommend the best café, the most beautiful square and the worst time to visit.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Recommend the cheapest restaurant you know.", expected = listOf("<Name> is the cheapest restaurant in town.", "The cheapest restaurant is <Name>."), focus = "the + -est", watch = "Superlatives need the: “the cheapest”, never just “cheapest”."), PracticeQuestion(prompt = "Describe a very famous place in your country. (long adjective)", expected = listOf("It's one of the most famous places in <country>."), focus = "the most + long adjective", watch = "“the famousest” doesn't exist — the most famous."), PracticeQuestion(prompt = "Which is correct: “the best” or “the most good”?", expected = listOf("the best"), focus = "irregular superlative", watch = "good → the best, bad → the worst."), PracticeQuestion(prompt = "Ask for the best way to get to the airport.", expected = listOf("What's the best way to get to the airport?"), focus = "asking for a recommendation", watch = "Fixed question: “What's the best way to …?”"), PracticeQuestion(prompt = "Say your favourite day of the week and why.", expected = listOf("My favourite day is <day> because …"), focus = "favourite + because", watch = "favourite already means “the one I like most”."), PracticeQuestion(prompt = "Complete: “This is one of ___ (old) bars in the city.”", expected = listOf("one of the oldest bars in the city"), focus = "one of the -est", watch = "one of + the + superlative + plural noun."))), exercises = listOf(Exercise(id = "en-foundations-compare-superlatives-e1", kind = "choice", prompt = "This is ___ café in the neighbourhood.", options = listOf("the most popular", "the popularest", "more popular", "popular"), answers = listOf("the most popular"), explain = "Long adjectives: the most + adjective."), Exercise(id = "en-foundations-compare-superlatives-e2", kind = "gap", prompt = "August is ___ (busy) month here.", options = listOf(), answers = listOf("the busiest"), explain = "busy → the busiest."), Exercise(id = "en-foundations-compare-superlatives-e3", kind = "order", prompt = "Recommend the best pizza.", options = listOf(), answers = listOf("This is the best pizza in the city"), explain = "the best + noun + in + place."), Exercise(id = "en-foundations-compare-superlatives-e4", kind = "written", prompt = "Fix: “It's most old building in town.”", options = listOf(), answers = listOf("it's the oldest building in town"), explain = "old → the oldest, and superlatives need the.")), skills = listOf("grammar:superlatives", "grammar:comparatives", "function:express-opinion", "vocab:town"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:comparatives")),
    Lesson(id = "en-foundations-compare-object-pronouns", title = "Object pronouns", goal = "Use me, you, him, her, it, us and them after verbs and prepositions.", intro = LessonIntro(explanation = listOf("After a verb, use the object pronoun: “Can you help me?” “I saw her yesterday.” “Call them later.”", "After prepositions too: “with me”, “for him”, “without them”, “between us”.", "it stays it; you stays you. Subject does the action, object receives it: “She loves him.”"), examples = listOf(ExampleLine(text = "Can you help me?", meaning = "object after a verb."), ExampleLine(text = "I saw them at the market.", meaning = "them = they."), ExampleLine(text = "This gift is for her.", meaning = "object after a preposition."), ExampleLine(text = "Come with us!", meaning = "us = we as object."), ExampleLine(text = "I'll call him tomorrow.", meaning = "him = he as object."), ExampleLine(text = "She works with me.", meaning = "me = I as object."))), expressions = listOf(TargetExpression(text = "verb + me/him/her/them/us", meaning = "The receiver of the action.", note = "Call me. Help us."), TargetExpression(text = "preposition + object pronoun", meaning = "with me, for him, to her.", note = "Never “with I”."), TargetExpression(text = "Let me …", meaning = "Offer or ask permission.", note = "Let me help you."), TargetExpression(text = "between us", meaning = "A secret or shared thing.", note = "Between you and me — never “between you and I”."), TargetExpression(text = "I don't understand it.", meaning = "it for things and ideas.", note = "it = this/that idea."), TargetExpression(text = "See you / See them later", meaning = "Goodbyes with objects.", note = "you stays the same.")), situation = "You are helping a new colleague settle in: offer help, introduce people, and explain who does what with whom.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Offer help to your new colleague.", expected = listOf("Let me help you.", "Can I help you?"), focus = "object pronouns", watch = "“Let me to help” — let takes the bare verb."), PracticeQuestion(prompt = "Say you saw Anna and Tom at the cinema. (them)", expected = listOf("I saw them at the cinema."), focus = "them", watch = "“I saw they” — subject vs object: they saw, saw them."), PracticeQuestion(prompt = "Your friend is carrying bags. Offer to carry one. (it)", expected = listOf("Let me carry it.", "Can I carry it for you?"), focus = "it", watch = "it replaces the thing: the bag → it."), PracticeQuestion(prompt = "Say this secret is between you and your friend. (between …)", expected = listOf("It's between you and me."), focus = "between you and me", watch = "Never “between you and I” — after a preposition use me."), PracticeQuestion(prompt = "Say you will call your parents tonight. (them)", expected = listOf("I'll call them tonight.", "I'm going to call them tonight."), focus = "them", watch = "“call to them” — no to: “call them”."), PracticeQuestion(prompt = "Say this chair is for your guest. (her)", expected = listOf("This chair is for her."), focus = "for + her", watch = "“for she” — prepositions take object pronouns."))), exercises = listOf(Exercise(id = "en-foundations-compare-object-pronouns-e1", kind = "choice", prompt = "Can you help ___? I can't lift this.", options = listOf("me", "I", "my", "mine"), answers = listOf("me"), explain = "After the verb, object pronoun: help me."), Exercise(id = "en-foundations-compare-object-pronouns-e2", kind = "gap", prompt = "This present is for ___. (Anna)", options = listOf(), answers = listOf("her"), explain = "Anna → her after a preposition."), Exercise(id = "en-foundations-compare-object-pronouns-e3", kind = "order", prompt = "Ask a friend to come along.", options = listOf(), answers = listOf("Come with us"), explain = "preposition + us."), Exercise(id = "en-foundations-compare-object-pronouns-e4", kind = "written", prompt = "Fix: “She loves he.”", options = listOf(), answers = listOf("she loves him"), explain = "he is the subject; the object is him.")), skills = listOf("grammar:object-pronouns", "grammar:subject-pronouns", "function:make-requests"), prerequisites = listOf("grammar:subject-pronouns"))))
}

object EnFoundationsPlans {
    val unit = CourseUnit(id = "en-foundations-plans", title = "Plans & advice", subtitle = "What's next", level = "A2", themes = listOf(ConversationTheme("weekend-trip", "The weekend trip", "What are you going to do?", "map", "Course", "You are planning a weekend trip together: say your plans, compare ideas and agree on a route.", 0),
                ConversationTheme("new-job-jitters", "The new job", "Rules and advice", "briefcase", "Course", "A friend starts a new job tomorrow. Talk about the rules (must, have to) and give friendly advice (should).", 1)), lessons = listOf(    Lesson(id = "en-foundations-plans-going-to", title = "Going to: plans", goal = "Talk about future plans and intentions with am/is/are going to.", intro = LessonIntro(explanation = listOf("Plans use be + going to + verb: “I'm going to visit my family. She's going to study tonight. We're going to move house.”", "Questions flip be: “Are you going to come?” Negatives add not: “I'm not going to work on Saturday.”", "going to is about intention — a plan already in your head. Time markers: tonight, tomorrow, next week, this weekend."), examples = listOf(ExampleLine(text = "I'm going to learn to cook.", meaning = "An intention."), ExampleLine(text = "She's going to start a new job.", meaning = "Her plan for the future."), ExampleLine(text = "We're going to travel in June.", meaning = "A plan with a date."), ExampleLine(text = "Are you going to watch the match?", meaning = "Ask about a plan."), ExampleLine(text = "I'm not going to pay for that!", meaning = "A refused plan."), ExampleLine(text = "It's going to rain tonight.", meaning = "A prediction with evidence — the clouds!"))), expressions = listOf(TargetExpression(text = "I'm going to + verb", meaning = "Your plan.", note = "I'm going to start running."), TargetExpression(text = "Are you going to …?", meaning = "Ask about plans.", note = "Are you going to join us?"), TargetExpression(text = "I'm not going to …", meaning = "A plan you refuse.", note = "I'm not going to stay late."), TargetExpression(text = "What are you going to do …?", meaning = "The classic plan question.", note = "… this weekend?"), TargetExpression(text = "It's going to …", meaning = "Prediction with evidence.", note = "Look at those clouds!"), TargetExpression(text = "next week / this weekend / tonight", meaning = "Anchor the plan in time.", note = "going to + time marker.")), situation = "You and a friend plan a free Saturday: say what you're going to do, ask about their plans and find something to do together.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ask your friend about their plans for the weekend.", expected = listOf("What are you going to do at the weekend?", "What are you going to do this weekend?"), focus = "the plan question", watch = "“What you going to do?” — the are is obligatory in careful English."), PracticeQuestion(prompt = "Say one plan you have for next month.", expected = listOf("I'm going to <verb> next month.", "Next month I'm going to <verb>."), focus = "I'm going to", watch = "“I going to travel” — be comes first: “I'm going to”."), PracticeQuestion(prompt = "The sky is very grey. What do you say? (rain)", expected = listOf("It's going to rain."), focus = "prediction with evidence", watch = "Present evidence → going to: “It's going to rain”."), PracticeQuestion(prompt = "Refuse politely: your friends want to stay out until 2am.", expected = listOf("I'm not going to stay out that late.", "I'm not going to stay until two."), focus = "negative plan", watch = "“I not going” — “I'm not going to”."), PracticeQuestion(prompt = "Ask if she is going to join the gym with you.", expected = listOf("Are you going to join the gym with me?"), focus = "are + going to", watch = "Questions flip be: “Are you going to…?”"), PracticeQuestion(prompt = "Say your plans after this course. (two sentences)", expected = listOf("I'm going to <activity> and I'm going to <activity>."), focus = "chaining plans", watch = "and joins two plans: “I'm going to practise and travel”."))), exercises = listOf(Exercise(id = "en-foundations-plans-going-to-e1", kind = "choice", prompt = "They ___ going to move to Lisbon.", options = listOf("are", "is", "do", "will"), answers = listOf("are"), explain = "With they: are going to."), Exercise(id = "en-foundations-plans-going-to-e2", kind = "gap", prompt = "I ___ ___ ___ study tonight. (3 words: intention of I)", options = listOf(), answers = listOf("am going to", "'m going to"), explain = "I am going to + verb."), Exercise(id = "en-foundations-plans-going-to-e3", kind = "order", prompt = "Ask about their evening plans.", options = listOf(), answers = listOf("What are you going to do tonight"), explain = "Question word + are + you + going to."), Exercise(id = "en-foundations-plans-going-to-e4", kind = "written", prompt = "Fix: “She going to start a course.”", options = listOf(), answers = listOf("she's going to start a course", "she is going to start a course"), explain = "She's going to — be is obligatory.")), skills = listOf("grammar:going-to", "function:make-future-plans", "speaking:describe-routine"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "en-foundations-plans-past-irregular", title = "Irregular past verbs", goal = "Tell past stories with the most common irregular verbs.", intro = LessonIntro(explanation = listOf("Many common verbs are irregular: go → went, see → saw, make → made, take → took, come → came, get → got.", "Negatives and questions return to the base form with did: “I didn't go. Did you see it?” The past lives only in the positive.", "Learn them in pairs: buy → bought, eat → ate, drink → drank, write → wrote, drive → drove, sleep → slept."), examples = listOf(ExampleLine(text = "We went to the coast last summer.", meaning = "go → went."), ExampleLine(text = "I saw your brother yesterday.", meaning = "see → saw."), ExampleLine(text = "She made a cake for my birthday.", meaning = "make → made."), ExampleLine(text = "I didn't take the umbrella.", meaning = "didn't + base form."), ExampleLine(text = "Did you eat anything?", meaning = "did + base form in questions."), ExampleLine(text = "He came home late and went to bed.", meaning = "Two irregulars in one story."))), expressions = listOf(TargetExpression(text = "go → went", meaning = "The most common of all.", note = "We went home early."), TargetExpression(text = "see → saw / take → took", meaning = "Everyday irregulars.", note = "I saw it, I took it."), TargetExpression(text = "make → made / come → came", meaning = "Story verbs.", note = "She made dinner; he came late."), TargetExpression(text = "didn't + base form", meaning = "Past negative.", note = "I didn't sleep well — not “didn't slept”."), TargetExpression(text = "Did you …?", meaning = "Past question.", note = "Did you get my message?"), TargetExpression(text = "yesterday / last night / ago", meaning = "Anchor the story.", note = "two weeks ago.")), situation = "You tell a friend about a disastrous day trip: what went wrong, what you saw, what you lost — all in the past.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Say where you went last weekend. (past, place)", expected = listOf("I went to <place> last weekend."), focus = "went", watch = "“I goed / I wented” — the irregular is went."), PracticeQuestion(prompt = "Say you didn't sleep well last night.", expected = listOf("I didn't sleep well last night."), focus = "didn't + base", watch = "“didn't slept” — after didn't, the verb is bare: sleep."), PracticeQuestion(prompt = "Ask if your friend saw the news yesterday.", expected = listOf("Did you see the news yesterday?"), focus = "did + see", watch = "“Did you saw” — after did, base form: see."), PracticeQuestion(prompt = "Tell one thing you made this week. (make)", expected = listOf("I made <thing> this week."), focus = "made", watch = "make → made, no -ed."), PracticeQuestion(prompt = "Say you came home late yesterday.", expected = listOf("I came home late yesterday."), focus = "came", watch = "come → came: “I come home late” is present."), PracticeQuestion(prompt = "Tell a mini story: where you went, what you saw, what you bought.", expected = listOf("I went to <place>, saw <thing> and bought <thing>."), focus = "three irregulars", watch = "One past story, three irregular verbs: went, saw, bought."))), exercises = listOf(Exercise(id = "en-foundations-plans-past-irregular-e1", kind = "choice", prompt = "Yesterday we ___ to the market.", options = listOf("went", "goed", "go", "gone"), answers = listOf("went"), explain = "go → went."), Exercise(id = "en-foundations-plans-past-irregular-e2", kind = "gap", prompt = "I ___ your keys on the table. (see, yesterday)", options = listOf(), answers = listOf("saw"), explain = "see → saw."), Exercise(id = "en-foundations-plans-past-irregular-e3", kind = "order", prompt = "Ask about their dinner.", options = listOf(), answers = listOf("Did you eat anything"), explain = "Did + you + base verb."), Exercise(id = "en-foundations-plans-past-irregular-e4", kind = "written", prompt = "Fix: “I didn't took the bus.”", options = listOf(), answers = listOf("i didn't take the bus"), explain = "After didn't: take, never took.")), skills = listOf("grammar:past-simple-irregular", "function:describe-past-events", "function:tell-a-story"), canDo = listOf("describe-past-events"), prerequisites = listOf("grammar:past-simple-regular")),
    Lesson(id = "en-foundations-plans-modals", title = "Advice & obligation", goal = "Give advice with should and talk about rules with must and have to.", intro = LessonIntro(explanation = listOf("should = good idea, advice: “You should rest. You shouldn't work tonight.” It never takes -s or to.", "must = obligation from the speaker; have to = obligation from outside (rules, timetables): “I must finish this.” “I have to wear a uniform.”", "Questions: “Should I call him?” “Do you have to work on Sundays?” Negatives: “You shouldn't smoke.” “I don't have to get up early.”"), examples = listOf(ExampleLine(text = "You should drink more water.", meaning = "Friendly advice."), ExampleLine(text = "You shouldn't eat so late.", meaning = "Negative advice."), ExampleLine(text = "I must finish this today.", meaning = "The speaker's own obligation."), ExampleLine(text = "She has to wear a uniform.", meaning = "An outside rule."), ExampleLine(text = "Do we have to book a table?", meaning = "Ask about a rule."), ExampleLine(text = "You don't have to come.", meaning = "No obligation — it's optional."))), expressions = listOf(TargetExpression(text = "You should + verb", meaning = "Advice.", note = "You should try it."), TargetExpression(text = "You shouldn't + verb", meaning = "Advice against.", note = "You shouldn't worry."), TargetExpression(text = "I must + verb", meaning = "Strong personal obligation.", note = "I must go now."), TargetExpression(text = "have to + verb", meaning = "Outside rules.", note = "I have to work on Saturdays."), TargetExpression(text = "don't have to", meaning = "No obligation — free choice.", note = "≠ mustn't! don't have to = optional."), TargetExpression(text = "Should I …?", meaning = "Ask for advice.", note = "Should I bring anything?")), situation = "A friend starts a new job tomorrow: give advice (should), tell them the rules of your office (have to) and say what is optional (don't have to).", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Your friend has an interview tomorrow. Give one piece of advice.", expected = listOf("You should sleep early.", "You should arrive early.", "You should prepare some questions."), focus = "should + verb", watch = "“You should to prepare” — no to after should."), PracticeQuestion(prompt = "Say one rule at your work. (have to)", expected = listOf("I have to <rule>.", "We have to <rule>."), focus = "have to", watch = "“I have to working” — have to + base verb."), PracticeQuestion(prompt = "Advise your friend NOT to check the phone all night.", expected = listOf("You shouldn't check your phone all night."), focus = "shouldn't", watch = "“You don't should” — the negative is shouldn't."), PracticeQuestion(prompt = "Say Sunday work is optional at your job.", expected = listOf("I don't have to work on Sundays.", "We don't have to work on Sundays."), focus = "don't have to", watch = "don't have to = optional; mustn't = prohibited!"), PracticeQuestion(prompt = "Ask if you need to bring anything to the party. (should)", expected = listOf("Should I bring anything?"), focus = "should question", watch = "“Do I should bring?” — should asks directly: “Should I…?”"), PracticeQuestion(prompt = "The doctor says it's necessary: take the medicine every day. (must)", expected = listOf("I must take the medicine every day.", "You must take the medicine every day."), focus = "must", watch = "must + base verb, no -s, no to."))), exercises = listOf(Exercise(id = "en-foundations-plans-modals-e1", kind = "choice", prompt = "You look tired. You ___ go to bed early.", options = listOf("should", "should to", "are should", "will should"), answers = listOf("should"), explain = "should + base verb — advice."), Exercise(id = "en-foundations-plans-modals-e2", kind = "gap", prompt = "At our office we have ___ wear a badge.", options = listOf(), answers = listOf("to"), explain = "have to + base verb for outside rules."), Exercise(id = "en-foundations-plans-modals-e3", kind = "order", prompt = "Tell your friend the visit is optional.", options = listOf(), answers = listOf("You don't have to come"), explain = "don't have to = no obligation."), Exercise(id = "en-foundations-plans-modals-e4", kind = "written", prompt = "Fix: “You shoulds rest.”", options = listOf(), answers = listOf("you should rest"), explain = "Modal verbs never take -s.")), skills = listOf("grammar:modal-should", "grammar:modal-must-have-to", "function:solve-problems", "vocab:work"), canDo = listOf("solve-everyday-problems"), prerequisites = listOf("grammar:present-simple"))))
}

object EnFoundationsStay {
    val unit = CourseUnit(id = "en-foundations-stay", title = "Staying somewhere", subtitle = "How much, how many, a room", level = "A2", themes = listOf(ConversationTheme("guest-room", "The guest room", "How much space?", "bed.double", "Course", "Family is visiting. Count the beds, the towels and the problems — is there enough room for everyone?", 0),
                ConversationTheme("booking-call", "The booking call", "A room for two nights", "phone", "Course", "You book accommodation by phone: dates, price, breakfast — and one special request.", 1)), lessons = listOf(    Lesson(id = "en-foundations-stay-quantifiers", title = "How much / how many", goal = "Ask about countable and uncountable things with how much and how many.", intro = LessonIntro(explanation = listOf("Countable things (bottles, rooms, tickets) take many: “How many rooms do you need?” Uncountable stuff (water, money, time) takes much: “How much water do you need?”", "In everyday questions, much alone sounds formal: “How much money?” is fine, but people say “How much is it?” — the full countable question needs many.", "Answers use a lot of / some / a few (countable) / a little (uncountable): “We need a few chairs and a little luck.”"), examples = listOf(ExampleLine(text = "How many guests are coming?", meaning = "Countable: guests."), ExampleLine(text = "How much milk is in the fridge?", meaning = "Uncountable: milk."), ExampleLine(text = "How much does it cost?", meaning = "Price always takes much."), ExampleLine(text = "We need a few more chairs.", meaning = "a few + countable."), ExampleLine(text = "There's a little time left.", meaning = "a little + uncountable."), ExampleLine(text = "A lot of people are coming.", meaning = "a lot of works with both."))), expressions = listOf(TargetExpression(text = "How many + plural?", meaning = "Count the things.", note = "How many nights?"), TargetExpression(text = "How much + uncountable?", meaning = "Measure the stuff.", note = "How much luggage?"), TargetExpression(text = "How much is/are …?", meaning = "Ask any price.", note = "How much are the towels?"), TargetExpression(text = "a few + plural", meaning = "A small number.", note = "a few days = algunos días."), TargetExpression(text = "a little + uncountable", meaning = "A small amount.", note = "a little sugar."), TargetExpression(text = "a lot of 