commodation-e4", kind = "written", prompt = "Make the special request politely: a room on a high floor.", options = listOf(), answers = listOf("would it be possible to have a room on a high floor", "could i have a room on a high floor please"), explain = "Would it be possible to have…?")), skills = listOf("vocab:travel", "function:solve-problems", "grammar:quantities", "vocab:social-expressions"), canDo = listOf("solve-everyday-problems", "use-transport"), prerequisites = listOf("grammar:quantities")),
