ay)", expected = listOf("I used to run every day."), focus = "used to", watch = "used to + base verb."), PracticeQuestion(prompt = "Say the present: no time now.", expected = listOf("Now I don't have time."), focus = "now", watch = "now + present simple."), PracticeQuestion(prompt = "Say you almost never cook these days.", expected = listOf("I hardly ever cook these days."), focus = "hardly ever", watch = "hardly ever = casi nunca."), PracticeQuestion(prompt = "Say one new habit you've started. (walking to work)", expected = listOf("I've started walking to work."), focus = "start + -ing", watch = "I've started + -ing: the new habit."), PracticeQuestion(prompt = "Say your weekends used to be active.", expected = listOf("My weekends used to be active."), focus = "used to", watch = "used to + verbo base."))), exercises = listOf(Exercise(id = "en-foundations-health-habits-e1", kind = "choice", prompt = "I ___ to run every day when I was a student.", options = listOf("used", "use", "was use", "am used"), answers = listOf("used"), explain = "Past habit: used to + verb."), Exercise(id = "en-foundations-health-habits-e2", kind = "gap", prompt = "I ___ ___ ever cook these days. (casi nunca)", options = listOf(), answers = listOf("hardly ever"), explain = "hardly ever = almost never."), Exercise(id = "en-foundations-health-habits-e3", kind = "order", prompt = "Say your new habit. (started / I've / walking / to work)", options = listOf(), answers = listOf("I've started walking to work"), explain = "I've started + -ing."), Exercise(id = "en-foundations-health-habits-e4", kind = "written", prompt = "Compare: sleep eight hours before, five now.", options = listOf(), answers = listOf("i used to sleep eight hours now i sleep five"), explain = "used to … now …")), skills = listOf("grammar:used-to", "grammar:frequency-adverbs", "grammar:present-perfect", "vocab:health"), canDo = listOf("solve-everyday-problems"), prerequisites = listOf("grammar:past-simple-irregular"))))
