                ConversationTheme("story-night", "Story night", "What was happening?", "moon.stars", "Course", "You tell a story with background: what was happening when something unexpected occurred.", 1)), lessons = listOf(    Lesson(id = "en-foundations-experiences-present-perfect", title = "Present perfect: experiences", goal = "Talk about life experiences with have/has + past participle, without saying when.", intro = LessonIntro(explanation = listOf("Experiences without a time use have/has + past participle: “I've visited Rome. She's never tried sushi. Have you been to Japan?”", "The moment you say WHEN, switch to past simple: “I've been to Rome. I went there in 2019.”", "Participates are irregular often: be → been, see → seen, go → gone/been, eat → eaten, do → done."), examples = listOf(ExampleLine(text = "I've never been to Asia.", meaning = "A life experience (not yet!)."), ExampleLine(text = "Have you ever tried paella?", meaning = "ever = in your life."), ExampleLine(text = "She's seen that film three times.", meaning = "Repeated experience."), ExampleLine(text = "We've just finished dinner.", meaning = "just = a moment ago."), ExampleLine(text = "I've already packed, but I haven't printed the tickets.", meaning = "already / not yet."), ExampleLine(text = "I went to Rome in 2019.", meaning = "WHEN given → past simple."))), expressions = listOf(TargetExpression(text = "I've (never/ever/already) …", meaning = "Experience, no date.", note = "I've never driven a van."), TargetExpression(text = "Have you ever …?", meaning = "The classic experience question.", note = "Reply: Yes, I have / No, I haven't."), TargetExpression(text = "I've just …", meaning = "Very recent.", note = "I've just arrived."), TargetExpression(text = "… twice / three times", meaning = "Count the experience.", note = "I've read it twice."), TargetExpression(text = "gone to vs been to", meaning = "gone = still there; been = visited and returned.", note = "She's gone to Rome (not back yet)."), TargetExpression(text = "When? → past simple", meaning = "The golden switch rule.", note = "I've been to Peru. I went in 2018.")), situation = "You meet a traveller at a hostel: swap life experiences with Have you ever…? and ask follow-up questions with past simple when they give a when.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ask a traveller if they have ever visited Japan.", expected = listOf("Have you ever been to Japan?", "Have you ever visited Japan?"), focus = "Have you ever…?", watch = "“Did you ever visit…?” is possible in AmE, but “Have you ever…?” is the safest form."), PracticeQuestion(prompt = "Answer negatively: you have never tried surfing.", expected = listOf("I've never tried surfing.", "I have never tried surfing."), focus = "never + participle", watch = "“I've never tried to surf” changes meaning slightly; keep “tried surfing”."), PracticeQuestion(prompt = "Say you visited Rome in 2019 (mention the year).", expected = listOf("I went to Rome in 2019."), focus = "when → past simple", watch = "“I've gone to Rome in 2019” — a finished time forbids the present perfect."), PracticeQuestion(prompt = "Your friend is not here — she went to the airport. Say it two ways.", expected = listOf("She's gone to the airport.", "She has gone to the airport."), focus = "gone to", watch = "“She's been to the airport” means she went and came back."), PracticeQuestion(prompt = "Say you have seen that film three times.", expected = listOf("I've seen that film three times.", "I have seen that film three times."), focus = "counting experiences", watch = "“I saw it three times” needs a past anchor; without one, prefer the present perfect."), PracticeQuestion(prompt = "Ask a follow-up when someone says “I've been to Iceland”.", expected = listOf("When did you go?", "What did you see there?", "How was it?"), focus = "switching to past", watch = "The follow-up asks about the trip → past simple."))), exercises = listOf(Exercise(id = "en-foundations-experiences-present-perfect-e1", kind = "choice", prompt = "___ you ever eaten octopus?", options = listOf("Have", "Did", "Are", "Do"), answers = listOf("Have"), explain = "Experience question: Have you ever…?"), Exercise(id = "en-foundations-experiences-present-perfect-e2", kind = "gap", prompt = "She's ___ (see) that exhibition twice.", options = listOf(), answers = listOf("seen"), explain = "see → seen with have/has."), Exercise(id = "en-foundations-experiences-present-perfect-e3", kind = "order", prompt = "Say it is very recent.", options = listOf(), answers = listOf("I've just arrived"), explain = "have + just + participle."), Exercise(id = "en-foundations-experiences-present-perfect-e4", kind = "written", prompt = "Fix: “I've visited Peru in 2018.”", options = listOf(), answers = listOf("i visited peru in 2018"), explain = "With a finished time (in 2018), use past simple.")), skills = listOf("grammar:present-perfect", "grammar:past-simple-irregular", "function:describe-past-events", "listening:inference"), canDo = listOf("describe-past-events"), prerequisites = listOf("grammar:past-simple-regular", "grammar:object-pronouns")),
    Lesson(id = "en-foundations-experiences-past-continuous", title = "Past continuous: background", goal = "Set the scene of a past story with was/were + -ing, and interrupt it with past simple.", intro = LessonIntro(explanation = listOf("Background actions use was/were + -ing: “It was raining. People were running. I was cooking.”", "The classic structure: past continuous (background) + when/until + past simple (event): “I was cooking when the lights went out.”", "Two parallel background actions use while: “While she was sleeping, he was reading.”"), examples = listOf(ExampleLine(text = "The sun was setting and the birds were singing.", meaning = "Scene painting."), ExampleLine(text = "I was cooking when the phone rang.", meaning = "Background + interruption."), ExampleLine(text = "They were waiting for the bus when it started to rain.", meaning = "Longer action + event."), ExampleLine(text = "While we were driving, it snowed.", meaning = "while + two past tenses."), ExampleLine(text = "What were you doing at midnight?", meaning = "Question about a past moment."), ExampleLine(text = "I wasn't listening, sorry.", meaning = "Negative background."))), expressions = listOf(TargetExpression(text = "was/were + -ing", meaning = "The background of the story.", note = "It was getting dark."), TargetExpression(text = "… when + past simple", meaning = "The event that interrupts.", note = "…when he appeared."), TargetExpression(text = "while + was/were -ing", meaning = "Two things at once.", note = "While I was waiting, I read."), TargetExpression(text = "What were you doing…?", meaning = "Ask about a past moment.", note = "…at eight last night?"), TargetExpression(text = "Suddenly, …", meaning = "Move from background to event.", note = "Suddenly, the door opened."), TargetExpression(text = "It was a normal evening when…", meaning = "The classic story opener.", note = "…everything changed.")), situation = "You and a friend swap short stories: set the scene with past continuous, then deliver the surprise event with past simple.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Set the scene: the rain / fall, and people / run for shelter.", expected = listOf("The rain was falling and people were running for shelter."), focus = "was/were + -ing", watch = "“The rain fell” is an event — the background is “was falling”."), PracticeQuestion(prompt = "Add the interruption: you were cooking / lights went out.", expected = listOf("I was cooking when the lights went out."), focus = "when + past simple", watch = "The short event takes past simple: “went out”, not “was going out”."), PracticeQuestion(prompt = "Ask what your friend was doing at ten last night.", expected = listOf("What were you doing at ten last night?"), focus = "were + -ing question", watch = "“What did you do at ten?” asks for an answer list; “were doing” asks about the moment."), PracticeQuestion(prompt = "Say two parallel actions: you drove / your partner read the map.", expected = listOf("While I was driving, my partner was reading the map."), focus = "while + continuous", watch = "Both long actions take the continuous after while."), PracticeQuestion(prompt = "Open a story: normal evening / everything changed.", expected = listOf("It was a normal evening when everything changed."), focus = "story opener", watch = "Background first (was), event second (changed)."), PracticeQuestion(prompt = "Negative background: you weren't listening when she told you.", expected = listOf("I wasn't listening when she told me."), focus = "wasn't + -ing", watch = "“I didn't listening” — negatives of the continuous use wasn't/weren't."))), exercises = listOf(Exercise(id = "en-foundations-experiences-past-continuous-e1", kind = "choice", prompt = "I ___ dinner when the doorbell rang.", options = listOf("was cooking", "cooked", "am cooking", "have cooked"), answers = listOf("was cooking"), explain = "Background action: was + -ing."), Exercise(id = "en-foundations-experiences-past-continuous-e2", kind = "gap", prompt = "While they ___ ___ (wait), the bus arrived.", options = listOf(), answers = listOf("were waiting"), explain = "Plural background: were + -ing."), Exercise(id = "en-foundations-experiences-past-continuous-e3", kind = "order", prompt = "Ask about a past moment. (you / at midnight / what / were / doing)", options = listOf(), answers = listOf("What were you doing at midnight"), explain = "Question word + were + you + -ing."), Exercise(id = "en-foundations-experiences-past-continuous-e4", kind = "written", prompt = "Fix: “While I cooked, she was watching TV.”", options = listOf(), answers = listOf("while i was cooking she was watching tv"), explain = "Both parallel long actions take the continuous: was cooking.")), skills = listOf("grammar:past-continuous", "grammar:past-simple-regular", "function:tell-a-story", "speaking:tell-past-story"), canDo = listOf("tell-a-story"), prerequisites = listOf("grammar:past-was-were", "grammar:present-continuous")),
    Lesson(id = "en-foundations-experiences-used-to", title = "Used to: past habits", goal = "Compare the past with now using used to / didn't use to.", intro = LessonIntro(explanation = listOf("Past habits that stopped use used to + verb: “I used to play outside every day. She used to live in Berlin.”", "Negative: didn't use to: “We didn't use to have a car.” Question: “Did you use to…?” Note: no -d in the negative/question.", "For states still true, prefer present simple; for single past events, past simple. used to is for repeated past routines that ended."), examples = listOf(ExampleLine(text = "I used to hate coffee. Now I love it.", meaning = "Past habit, changed."), ExampleLine(text = "There used to be a cinema here.", meaning = "Past state that ended."), ExampleLine(text = "We didn't use to lock the door.", meaning = "Past absence of a habit."), ExampleLine(text = "Did people use to write letters?", meaning = "Question form."), ExampleLine(text = "He didn't use to cook — now he's a chef!", meaning = "Big change."), ExampleLine(text = "I used to walk to school.", meaning = "Routine when you were young."))), expressions = listOf(TargetExpression(text = "used to + verb", meaning = "A past habit that stopped.", note = "I used to smoke."), TargetExpression(text = "didn't use to + verb", meaning = "Something you didn't do before.", note = "No -d after use here."), TargetExpression(text = "Did you use to …?", meaning = "Ask about old habits.", note = "Did you use to play an instrument?"), TargetExpression(text = "… but now …", meaning = "The contrast sentence.", note = "I used to walk, but now I cycle."), TargetExpression(text = "There used to be …", meaning = "Past places and things.", note = "There used to be a lake here."), TargetExpression(text = "be used to + -ing", meaning = "Different! = estar acostumbrado a.", note = "I'm used to getting up early.")), situation = "You look at old photos with a friend: compare childhood habits with life now using used to, didn't use to and but now.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Say one childhood habit you have stopped.", expected = listOf("I used to <habit>."), focus = "used to", watch = "“I used to played” — used to + base verb."), PracticeQuestion(prompt = "Say something about your town that no longer exists. (There used to…)", expected = listOf("There used to be <place>.", "There used to be a market here."), focus = "There used to be", watch = "“There used to have” is wrong — use be for places/things."), PracticeQuestion(prompt = "Say you didn't like vegetables before.", expected = listOf("I didn't use to like vegetables.", "I used to not like vegetables."), focus = "didn't use to", watch = "Careful spelling: didn't use to (no -d)."), PracticeQuestion(prompt = "Ask a friend about an old habit. (instrument / sport)", expected = listOf("Did you use to play an instrument?", "Did you use to do any sport?"), focus = "Did you use to…?", watch = "“Did you used to…?” — in questions, use to loses the -d."), PracticeQuestion(prompt = "Contrast: past walk to school, now cycle.", expected = listOf("I used to walk to school, but now I cycle."), focus = "but now", watch = "The contrast word now makes the change explicit."), PracticeQuestion(prompt = "Say you are accustomed to early mornings. (be used to)", expected = listOf("I'm used to getting up early."), focus = "be used to + -ing", watch = "Different structure: be used to + -ing = estar acostumbrado."))), exercises = listOf(Exercise(id = "en-foundations-experiences-used-to-e1", kind = "choice", prompt = "She ___ live in Berlin when she was young.", options = listOf("used to", "use to", "was used to", "would been"), answers = listOf("used to"), explain = "Past habit: used to + verb."), Exercise(id = "en-foundations-experiences-used-to-e2", kind = "gap", prompt = "We ___ ___ ___ have a car. (negative, 3 words)", options = listOf(), answers = listOf("didn't use to", "did not use to"), explain = "didn't use to — no -d."), Exercise(id = "en-foundations-experiences-used-to-e3", kind = "order", prompt = "Ask about old habits. (you / use / play / did / to / an instrument)", options = listOf(), answers = listOf("Did you use to play an instrument"), explain = "Did + you + use to + base verb."), Exercise(id = "en-foundations-experiences-used-to-e4", kind = "written", prompt = "Fix: “I'm used to get up early.”", options = listOf(), answers = listOf("i'm used to getting up early", "i am used to getting up early"), explain = "be used to + -ing: getting.")), skills = listOf("grammar:used-to", "grammar:past-simple-irregular", "function:tell-a-story", "vocab:daily-routine"), canDo = listOf("tell-a-story"), prerequisites = listOf("grammar:past-simple-irregular")),
    Lesson(id = "en-foundations-experiences-story-writing", title = "Writing your story", goal = "Turn an experience into a short written story with a beginning, a turn and an ending.", intro = LessonIntro(explanation = listOf("Written stories breathe: short sentences for tension, long ones for scenery. Start in the middle: “The lock wouldn't turn.”", "Spine: opening moment → the turn (when/until/suddenly) → the ending feeling. Three paragraphs, 80-120 words.", "Show, don't label: not “it was a bad day” but “my keys, my phone and my umbrella were all on the kitchen table — together, at home, where I wasn't.”"), examples = listOf(ExampleLine(text = "The lock wouldn't turn.", meaning = "Open in the middle of the trouble."), ExampleLine(text = "It started fine: sun, coffee, an early train.", meaning = "A calm before."), ExampleLine(text = "Until the announcement, everything was normal.", meaning = "until signals the turn."), ExampleLine(text = "Suddenly, the platform emptied.", meaning = "sudden movement, short sentence."), ExampleLine(text = "By the time I got home, I'd laughed about it twice.", meaning = "Ending with distance."), ExampleLine(text = "Some days you're the tourist, even in your own city.", meaning = "A closing thought."))), expressions = listOf(TargetExpression(text = "Open in the middle", meaning = "First line = trouble or action.", note = "Skip the weather report."), TargetExpression(text = "until / when + the turn", meaning = "Move the plot.", note = "Until the doors closed…"), TargetExpression(text = "Suddenly, + short sentence", meaning = "Pace change.", note = "Short = tense."), TargetExpression(text = "By the time …, …", meaning = "Close with distance.", note = "By the time + past, past perfect feels natural."), TargetExpression(text = "a closing thought", meaning = "One reflective line.", note = "Some days you win, some days you learn."), TargetExpression(text = "80-120 words", meaning = "The short-story sweet spot.", note = "Every sentence earns its place.")), situation = "You write a 100-word story for the class blog: a travel day that went wrong — opening in the middle, one turn, one closing thought.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open your story in the middle of the trouble. (the lock)", expected = listOf("The lock wouldn't turn."), focus = "the opening", watch = "“Last summer I travelled…” is a report, not a story."), PracticeQuestion(prompt = "Set the calm before: sun, coffee, an early train.", expected = listOf("It started fine: sun, coffee, an early train."), focus = "the calm", watch = "A calm first line makes the turn hit harder."), PracticeQuestion(prompt = "Signal the turn: the announcement changed everything. (until)", expected = listOf("Until the announcement, everything was normal."), focus = "until", watch = "until + noun/clause marks the exact turn."), PracticeQuestion(prompt = "Add pace: the platform emptied suddenly. (short sentence)", expected = listOf("Suddenly, the platform emptied."), focus = "suddenly", watch = "One-word openers (Suddenly, Luckily) control pace."), PracticeQuestion(prompt = "Close with distance and humour.", expected = listOf("By the time I got home, I'd laughed about it twice."), focus = "the ending", watch = "Distance turns disaster into story."), PracticeQuestion(prompt = "Add a one-line reflection to close.", expected = listOf("Some days you're the tourist, even in your own city."), focus = "the thought", watch = "One line, not a moral lecture."))), exercises = listOf(Exercise(id = "en-foundations-experiences-story-writing-e1", kind = "choice", prompt = "Which opening starts IN the trouble?", options = listOf("The lock wouldn't turn.", "Last summer I travelled a lot.", "It was a sunny day in June.", "I want to tell you about trains."), answers = listOf("The lock wouldn't turn."), explain = "In medias res: start inside the problem."), Exercise(id = "en-foundations-experiences-story-writing-e2", kind = "gap", prompt = "___ the doors closed, we realised the mistake.", options = listOf(), answers = listOf("when", "until"), explain = "when/until mark the turn."), Exercise(id = "en-foundations-experiences-story-writing-e3", kind = "order", prompt = "Add pace to the escape.", options = listOf(), answers = listOf("Suddenly the platform emptied"), explain = "Suddenly + short clause."), Exercise(id = "en-foundations-experiences-story-writing-e4", kind = "written", prompt = "Write a one-line closing thought for a travel disaster story.", options = listOf(), answers = listOf("some days you're the tourist even in your own city", "some days you win some days you learn", "at least i have a story now"), explain = "Reflective, light, one line.")), skills = listOf("writing:story", "grammar:connectors", "grammar:past-continuous", "function:tell-a-story", "speaking:tell-past-story"), canDo = listOf("tell-a-story"), prerequisites = listOf("grammar:past-continuous"))))
}

object EnFoundationsConnections {
    val unit = CourseUnit(id = "en-foundations-connections", title = "Opinions & connections", subtitle = "If, which, however", level = "B1", themes = listOf(ConversationTheme("plan-b", "Plan B", "If it rains…", "cloud.bolt", "Course", "Your outdoor plan is at risk. Negotiate conditionals: if this happens, we'll do that.", 0),
                ConversationTheme("movie-debate", "The film debate", "Which one? However…", "film", "Course", "You review a film together: describe scenes with relative clauses and connect opinions with however and although.", 1)), lessons = listOf(    Lesson(id = "en-foundations-connections-first-conditional", title = "First conditional", goal = "Talk about real future possibilities with if + present, will + verb.", intro = LessonIntro(explanation = listOf("Real future conditions: “If it rains, we'll stay in.” The if-clause uses present simple; the result uses will.", "Order can flip, but the comma disappears: “We'll stay in if it rains.” Never will inside the if-clause.", "Variations: “If it rains, we might stay in / we can stay in / let's stay in.”"), examples = listOf(ExampleLine(text = "If it rains, we'll stay home.", meaning = "The basic pattern."), ExampleLine(text = "We'll be late if the bus doesn't come.", meaning = "Result first, no comma."), ExampleLine(text = "If you help me, I'll help you.", meaning = "An exchange."), ExampleLine(text = "If they don't hurry, they'll miss the train.", meaning = "Negative in the if-clause."), ExampleLine(text = "If I see him, I might tell him.", meaning = "might = less certain."), ExampleLine(text = "What will you do if it snows?", meaning = "The question form."))), expressions = listOf(TargetExpression(text = "If + present, will + verb", meaning = "Real future possibility.", note = "If it rains, we'll stay in."), TargetExpression(text = "… if + present", meaning = "Result first, no comma.", note = "I'll call you if I'm late."), TargetExpression(text = "If not, … / Otherwise, …", meaning = "The other branch.", note = "Otherwise we'll drive."), TargetExpression(text = "might / can + verb", meaning = "Softer results.", note = "If it's cheap, we might buy it."), TargetExpression(text = "What will happen if …?", meaning = "Ask about consequences.", note = "…if the flight is cancelled?"), TargetExpression(text = "as long as / unless", meaning = "Condition cousins.", note = "unless = if not.")), situation = "You plan an outdoor birthday with a friend: set conditions for every possible problem (rain, no bus, cold) and what you'll do in each case.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "It may rain. Say what you will do. (stay in)", expected = listOf("If it rains, we'll stay in.", "If it rains, I'll stay in."), focus = "if + present, will", watch = "“If it will rain” — never will in the if-clause."), PracticeQuestion(prompt = "The bus may not come. Predict lateness.", expected = listOf("If the bus doesn't come, we'll be late.", "We'll be late if the bus doesn't come."), focus = "negative condition", watch = "“If the bus won't come” — present simple after if."), PracticeQuestion(prompt = "Offer an exchange of help.", expected = listOf("If you help me, I'll help you."), focus = "exchange", watch = "Both halves stay simple: present + will."), PracticeQuestion(prompt = "Ask about a cancelled flight. (what / you / do)", expected = listOf("What will you do if the flight is cancelled?"), focus = "the conditional question", watch = "will goes in the result question, not after if."), PracticeQuestion(prompt = "Soften the result: if it's cheap, maybe buy it.", expected = listOf("If it's cheap, I might buy it.", "If it's cheap, we might buy it."), focus = "might", watch = "might + base verb: “might to buy” is wrong."), PracticeQuestion(prompt = "Say the alternative: no picnic → restaurant.", expected = listOf("If we can't have a picnic, we'll go to a restaurant.", "Otherwise, we'll go to a restaurant."), focus = "otherwise", watch = "Otherwise connects to the previous sentence's failure."))), exercises = listOf(Exercise(id = "en-foundations-connections-first-conditional-e1", kind = "choice", prompt = "If it ___ tomorrow, we'll cancel the trip.", options = listOf("rains", "will rain", "rained", "is going to rain"), answers = listOf("rains"), explain = "The if-clause takes present simple."), Exercise(id = "en-foundations-connections-first-conditional-e2", kind = "gap", prompt = "I'll call you if I ___ late. (be)", options = listOf(), answers = listOf("am", "'m"), explain = "Present simple after if: if I am late."), Exercise(id = "en-foundations-connections-first-conditional-e3", kind = "order", prompt = "Ask about a snow plan.", options = listOf(), answers = listOf("What will you do if it snows"), explain = "Question word + will + you + do + if + present."), Exercise(id = "en-foundations-connections-first-conditional-e4", kind = "written", prompt = "Fix: “If it will rain, we stay in.”", options = listOf(), answers = listOf("if it rains we'll stay in", "if it rains we will stay in"), explain = "Present after if, will in the result.")), skills = listOf("grammar:first-conditional", "grammar:future-forms", "function:make-future-plans", "function:solve-problems"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:present-simple", "grammar:going-to")),
    Lesson(id = "en-foundations-connections-relative-clauses", title = "Relative clauses", goal = "Join ideas with who, which, that and where.", intro = LessonIntro(explanation = listOf("who joins people, which joins things, that joins both (informal): “The woman who lives upstairs is a doctor.” “The book which won the prize…”", "where joins places: “That's the café where we met.”", "Shortened clauses: “The man standing there” (= who is standing). No double subject: “the book which won” not “the book which it won”."), examples = listOf(ExampleLine(text = "The woman who lives upstairs is a doctor.", meaning = "who + person."), ExampleLine(text = "It's a film which changed cinema.", meaning = "which + thing."), ExampleLine(text = "The song that she wrote became famous.", meaning = "that for people too (informal)."), ExampleLine(text = "That's the café where we first met.", meaning = "where + place."), ExampleLine(text = "The train (that) we caught was late.", meaning = "that can disappear as object."), ExampleLine(text = "The guy standing by the door is my cousin.", meaning = "Shortened: who is standing."))), expressions = listOf(TargetExpression(text = "the person who …", meaning = "Identify people.", note = "The person who called left a message."), TargetExpression(text = "the thing which/that …", meaning = "Identify things.", note = "The app which tracks habits."), TargetExpression(text = "the place where …", meaning = "Identify places.", note = "the street where I grew up."), TargetExpression(text = "(that) … as object", meaning = "The joining word can vanish.", note = "the film (that) we saw."), TargetExpression(text = "…, which …", meaning = "Comment on the whole sentence.", note = "He was late, which annoyed everyone."), TargetExpression(text = "all / something + that", meaning = "Fixed pairs.", note = "All that matters is…")), situation = "You describe your neighbourhood to a visitor: the people who live there, the shops which are worth it and the corner where everything happens.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Describe your best friend. (person who…)", expected = listOf("My best friend is the person who knows me best.", "She's someone who always listens."), focus = "who", watch = "People take who (or that), never which."), PracticeQuestion(prompt = "Describe an app you like. (app which…)", expected = listOf("It's an app which helps me study.", "It's an app that tracks my habits."), focus = "which/that", watch = "Things take which or that — both are fine here."), PracticeQuestion(prompt = "Talk about the place you grew up. (where)", expected = listOf("The town where I grew up is small.", "I grew up in a village where everyone knew everyone."), focus = "where", watch = "where replaces “in which”: “the town where I grew up”."), PracticeQuestion(prompt = "Join: “The train was late. We caught it.”", expected = listOf("The train (that) we caught was late."), focus = "dropping that", watch = "When the joiner is the object, that can disappear."), PracticeQuestion(prompt = "Comment on a whole fact: “He resigned, … surprised everyone.”", expected = listOf("He resigned, which surprised everyone."), focus = ", which", watch = "Comma + which comments on the whole idea — never “, what surprised”."), PracticeQuestion(prompt = "Fix: “The book which it won the prize is long.”", expected = listOf("the book which won the prize is long"), focus = "no double subject", watch = "which replaces it — never both."))), exercises = listOf(Exercise(id = "en-foundations-connections-relative-clauses-e1", kind = "choice", prompt = "The woman ___ lives upstairs is a doctor.", options = listOf("who", "which", "where", "what"), answers = listOf("who"), explain = "People take who."), Exercise(id = "en-foundations-connections-relative-clauses-e2", kind = "gap", prompt = "That's the café ___ we first met.", options = listOf(), answers = listOf("where"), explain = "Places take where."), Exercise(id = "en-foundations-connections-relative-clauses-e3", kind = "order", prompt = "Identify the film.", options = listOf(), answers = listOf("It's a film which changed cinema"), explain = "which/that + verb."), Exercise(id = "en-foundations-connections-relative-clauses-e4", kind = "written", prompt = "Join: “He resigned. It annoyed everyone.” (use which)", options = listOf(), answers = listOf("he resigned which annoyed everyone"), explain = "He resigned, which annoyed everyone.")), skills = listOf("grammar:relative-clauses", "grammar:object-pronouns", "function:describe-people", "vocab:town"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:object-pronouns")),
    Lesson(id = "en-foundations-connections-connectors", title = "Connectors: although, however, so", goal = "Link ideas with contrast (although, however) and result (so, because).", intro = LessonIntro(explanation = listOf("Contrast: although + clause (“Although it was late, we went out”) and however + comma (“It was late. However, we went out.”).", "Result: so joins cause → effect (“It was late, so we took a taxi”). Reason: because joins effect → cause (“We took a taxi because it was late”).", "Punctuation: however needs a full stop or semicolon before it; although and because live inside the clause."), examples = listOf(ExampleLine(text = "Although it was expensive, we bought it.", meaning = "Contrast first."), ExampleLine(text = "We bought it. However, we regret it now.", meaning = "However starts a new sentence."), ExampleLine(text = "It was raining, so we stayed in.", meaning = "Cause → result."), ExampleLine(text = "We stayed in because it was raining.", meaning = "Result → reason."), ExampleLine(text = "The film was long; nevertheless, we enjoyed it.", meaning = "A formal contrast."), ExampleLine(text = "Therefore, the plan changed.", meaning = "Formal result."))), expressions = listOf(TargetExpression(text = "Although + clause, …", meaning = "Contrast inside one sentence.", note = "Although he's young, he leads the team."), TargetExpression(text = "… . However, …", meaning = "Contrast between sentences.", note = "It works. However, it's slow."), TargetExpression(text = "… , so + result", meaning = "Cause then result.", note = "It was full, so we left."), TargetExpression(text = "… because + reason", meaning = "Result then reason.", note = "I left because it was full."), TargetExpression(text = "Even though", meaning = "Stronger although.", note = "Even though I knew, I forgot."), TargetExpression(text = "despite + noun/-ing", meaning = "Contrast without a clause.", note = "Despite the rain, we walked.")), situation = "You and a colleague review a project: what worked, what failed, and why — connecting every point with so, because, although and however.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Contrast in one sentence: it was expensive / we bought it. (although)", expected = listOf("Although it was expensive, we bought it."), focus = "although", watch = "although + full clause with a verb, not a noun."), PracticeQuestion(prompt = "Contrast across two sentences: the plan works / it's slow. (however)", expected = listOf("The plan works. However, it's slow.", "The plan works; however, it's slow."), focus = "however", watch = "however needs a stop before it: full stop or semicolon."), PracticeQuestion(prompt = "Cause and result: the shop was full / we left. (so)", expected = listOf("The shop was full, so we left."), focus = "so", watch = "so joins cause → result with just a comma."), PracticeQuestion(prompt = "Same idea with because.", expected = listOf("We left because the shop was full."), focus = "because", watch = "because introduces the reason: result + because + reason."), PracticeQuestion(prompt = "Stronger contrast: you knew / you forgot. (even though)", expected = listOf("Even though I knew, I forgot."), focus = "even though", watch = "Same grammar as although, stronger feeling."), PracticeQuestion(prompt = "Contrast with a noun: the rain / we walked. (despite)", expected = listOf("Despite the rain, we walked.", "We walked despite the rain."), focus = "despite + noun", watch = "despite takes a noun or -ing, never a full clause."))), exercises = listOf(Exercise(id = "en-foundations-connections-connectors-e1", kind = "choice", prompt = "___ it was late, we went out.", options = listOf("Although", "However", "So", "Because"), answers = listOf("Although"), explain = "although + clause expresses contrast."), Exercise(id = "en-foundations-connections-connectors-e2", kind = "gap", prompt = "It was raining, ___ we stayed in. (result)", options = listOf(), answers = listOf("so"), explain = "so introduces the result."), Exercise(id = "en-foundations-connections-connectors-e3", kind = "order", prompt = "Give the reason for leaving.", options = listOf(), answers = listOf("We left because it was full"), explain = "result + because + reason."), Exercise(id = "en-foundations-connections-connectors-e4", kind = "written", prompt = "Fix: “The plan works, however it's slow.” (punctuation)", options = listOf(), answers = listOf("the plan works however it's slow", "the plan works however it is slow"), explain = "However needs a stronger break: “The plan works. However, it's slow.”")), skills = listOf("grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "writing:argument"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-foundations-connections-suggestions", title = "Making suggestions", goal = "Propose plans with Why don't we, How about and Let's — and accept or decline kindly.", intro = LessonIntro(explanation = listOf("Three openers, three grammars: Why don't we + verb (“Why don't we order pizza?”), How about + -ing (“How about watching a film?”), Let's + verb (“Let's stay in.”).", "Accept: “Sounds good!” “Good idea!” Decline kindly with a reason and a counter-offer: “I'm beat, honestly. Rain check?”", "Ask back with Shall we…? and What about…?: “Shall we meet at eight? What about the new place?”"), examples = listOf(ExampleLine(text = "Why don't we order pizza?", meaning = "why don't we + base verb."), ExampleLine(text = "How about trying the new ramen place?", meaning = "how about + -ing."), ExampleLine(text = "Let's stay in tonight.", meaning = "let's + base verb."), ExampleLine(text = "Sounds good — I'm in!", meaning = "Accepting."), ExampleLine(text = "I'm beat, honestly. Rain check?", meaning = "Declining kindly."), ExampleLine(text = "Shall we say eight, then?", meaning = "Closing the plan."))), expressions = listOf(TargetExpression(text = "Why don't we + verb", meaning = "Suggestion as a question.", note = "Never “Why we don't”."), TargetExpression(text = "How about + -ing", meaning = "Suggestion with a gerund.", note = "How about going…?"), TargetExpression(text = "Let's + verb", meaning = "Direct suggestion for both.", note = "Let's not argue."), TargetExpression(text = "Sounds good / I'm in!", meaning = "Accept.", note = "sounds + adjective, no subject."), TargetExpression(text = "Rain check?", meaning = "Not today, but soon.", note = "From ticket rain checks."), TargetExpression(text = "Shall we say …?", meaning = "Fix the detail.", note = "Time or place closer.")), situation = "Friday night, no plan: trade suggestions, accept one, decline another kindly and settle on a time and place.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Suggest ordering food in. (why don't we)", expected = listOf("Why don't we order in?"), focus = "why don't we", watch = "“Why we don't order” — the inversion lives in don't we."), PracticeQuestion(prompt = "Suggest watching a film. (how about)", expected = listOf("How about watching a film?"), focus = "how about + -ing", watch = "“How about to watch” — the gerund is obligatory."), PracticeQuestion(prompt = "Suggest staying in, directly.", expected = listOf("Let's stay in tonight."), focus = "let's", watch = "let's + base verb: “let's to stay” is wrong."), PracticeQuestion(prompt = "Accept a plan with enthusiasm.", expected = listOf("Sounds good — I'm in!", "Great idea, I'm in!"), focus = "accepting", watch = "“It sounds good” also works; “Sounds good” is the chatty form."), PracticeQuestion(prompt = "Decline tonight, but keep the plan alive.", expected = listOf("I'm beat, honestly. Rain check?", "Can't tonight — rain check?"), focus = "declining", watch = "A decline without a counter-offer ends the friendship chat."), PracticeQuestion(prompt = "Fix the time: eight.", expected = listOf("Shall we say eight, then?"), focus = "closing", watch = "shall we say + the detail."))), exercises = listOf(Exercise(id = "en-foundations-connections-suggestions-e1", kind = "choice", prompt = "How about ___ the new exhibition?", options = listOf("visiting", "to visit", "visit", "we visit"), answers = listOf("visiting"), explain = "How about + -ing."), Exercise(id = "en-foundations-connections-suggestions-e2", kind = "gap", prompt = "Why ___ we take a break? (suggestion)", options = listOf(), answers = listOf("don't"), explain = "Why don't we + base verb."), Exercise(id = "en-foundations-connections-suggestions-e3", kind = "order", prompt = "Suggest staying in.", options = listOf(), answers = listOf("Let's stay in tonight"), explain = "Let's + base verb."), Exercise(id = "en-foundations-connections-suggestions-e4", kind = "written", prompt = "Decline tonight kindly and keep it alive.", options = listOf(), answers = listOf("i'm beat rain check", "cant tonight rain check", "i can't tonight rain check"), explain = "Reason + rain check.")), skills = listOf("function:make-suggestions", "grammar:gerunds-infinitives", "grammar:connectors", "speaking:sustained-conversation"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:present-simple"))))
}

object EnFoundationsChange {
    val unit = CourseUnit(id = "en-foundations-change", title = "Changes", subtitle = "Will, rumours, phrasal verbs", level = "B1", themes = listOf(ConversationTheme("weather-pool", "The office pool", "What will happen?", "cloud.sun", "Course", "You and your colleagues bet on next week: weather, results, deadlines. Make predictions and defend them.", 0),
                ConversationTheme("rumour-mill", "The rumour mill", "Who said what?", "person.2.wave.2", "Course", "Office news travels fast: report what people said, and work out what is actually true.", 1)), lessons = listOf(    Lesson(id = "en-foundations-change-will", title = "Will: decisions & promises", goal = "Use will for spontaneous decisions, offers, promises and predictions without evidence.", intro = LessonIntro(explanation = listOf("Will is for the moment of speaking: “The phone's ringing — I'll get it!” The decision happens as you talk.", "It also covers promises and offers: “I'll always be there for you.” “I'll carry that for you.” And predictions without evidence: “You'll love this film.”", "Contrast with going to: going to = already decided before speaking (“I'm going to study tonight”); will = decided now (“OK, I'll study with you”).", "Negative: won't. Question: “Will you help me?” Never “will to help”."), examples = listOf(ExampleLine(text = "The phone's ringing — I'll get it!", meaning = "Decision at the moment of speaking."), ExampleLine(text = "I'll carry that for you.", meaning = "An offer."), ExampleLine(text = "I won't tell anyone, promise.", meaning = "A promise."), ExampleLine(text = "Don't worry, you'll pass.", meaning = "A prediction, no evidence given."), ExampleLine(text = "Shall I open the window? — Good idea, I'll close the door.", meaning = "Offers and instant decisions."), ExampleLine(text = "I'm going to study tonight. — Great, I'll join you.", meaning = "Plan vs decision now."))), expressions = listOf(TargetExpression(text = "I'll + verb", meaning = "Decision now, offer.", note = "I'll get the door."), TargetExpression(text = "I won't + verb", meaning = "Promise not to.", note = "I won't be late."), TargetExpression(text = "You'll love / it'll work", meaning = "Prediction without evidence.", note = "Contrast: it's going to rain (clouds!)."), TargetExpression(text = "Will you …?", meaning = "Request or prediction question.", note = "Will you help me?"), TargetExpression(text = "I think / probably + will", meaning = "Soften predictions.", note = "It'll probably rain."), TargetExpression(text = "vs going to", meaning = "Decided now vs decided before.", note = "Both futures, different moments.")), situation = "A friend's flat has a small crisis (broken lamp, hungry cat, empty fridge): make instant offers, promises and confident predictions as events unfold.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "The doorbell rings while you're both cooking. Offer to answer.", expected = listOf("I'll get it!", "I'll answer it!"), focus = "decision now", watch = "“I'm going to get it” sounds pre-planned — the ring is news."), PracticeQuestion(prompt = "Promise your friend you won't be late tomorrow.", expected = listOf("I won't be late.", "I promise I won't be late."), focus = "promise", watch = "“I won't to be” — won't + base verb."), PracticeQuestion(prompt = "No evidence yet: predict your friend will love the film.", expected = listOf("You'll love the film.", "You're going to love it? no — use will: You'll love it."), focus = "bare prediction", watch = "Without evidence, will is the natural choice."), PracticeQuestion(prompt = "Offer to carry the heavy boxes.", expected = listOf("I'll carry the boxes.", "I'll carry them for you."), focus = "offers", watch = "“I carry them” — English needs will for the offer."), PracticeQuestion(prompt = "Soften your prediction about tonight's traffic. (probably)", expected = listOf("It'll probably be terrible.", "Traffic will probably be bad."), focus = "probably + will", watch = "probably goes before will: “will probably be”."), PracticeQuestion(prompt = "Your friend says “I'm going to clean the kitchen”. Join in spontaneously.", expected = listOf("OK, I'll clean the bathroom!", "I'll help you then."), focus = "plan vs decision", watch = "Their plan = going to; your reaction = will."))), exercises = listOf(Exercise(id = "en-foundations-change-will-e1", kind = "choice", prompt = "The phone's ringing — I ___ answer it.", options = listOf("'ll", "going to", "am", "do"), answers = listOf("'ll"), explain = "A decision at the moment of speaking takes will."), Exercise(id = "en-foundations-change-will-e2", kind = "gap", prompt = "Don't worry, you ___ ___ fail. (negative promise)", options = listOf(), answers = listOf("will not", "won't"), explain = "won't + base verb."), Exercise(id = "en-foundations-change-will-e3", kind = "order", prompt = "Make a confident prediction.", options = listOf(), answers = listOf("You will love this film"), explain = "will + base verb, no evidence needed."), Exercise(id = "en-foundations-change-will-e4", kind = "written", prompt = "Your hands are full. Offer to be helped… no: offer help with the door.", options = listOf(), answers = listOf("i'll open the door", "i will open the door", "i'll get the door"), explain = "I'll + verb for instant offers.")), skills = listOf("grammar:future-forms", "function:make-future-plans", "function:describe-goals", "speaking:short-answer"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:verb-be", "grammar:going-to")),
    Lesson(id = "en-foundations-change-reported", title = "He said he was busy", goal = "Report what people said with said/thought + a tense shift back.", intro = LessonIntro(explanation = listOf("Direct: “I'm busy.” Reported: “He said he was busy.” The present shifts one step into the past.", "Common shifts: am/is → was, are → were, will → would, can → could, have → had. Past simple usually stays past simple.", "Questions drop their question form: “Where do you live?” → “She asked where I lived.” No do/did, no inversion."), examples = listOf(ExampleLine(text = "She said she was tired.", meaning = "“I am tired” → was."), ExampleLine(text = "They said they would call.", meaning = "“We will call” → would."), ExampleLine(text = "He told me he couldn't come.", meaning = "tell + person; say + (that)."), ExampleLine(text = "You said you liked my cooking!", meaning = "“I like” → liked."), ExampleLine(text = "She asked where I lived.", meaning = "Reported question, no did."), ExampleLine(text = "I thought you were leaving today.", meaning = "thought + shift."))), expressions = listOf(TargetExpression(text = "said (that) + shifted tense", meaning = "Report statements.", note = "He said (that) he was busy."), TargetExpression(text = "told me + shifted tense", meaning = "Report to a person.", note = "tell SOMEONE; never “said me”."), TargetExpression(text = "am/is → was", meaning = "The basic shift.", note = "“I'm here” → she said she was there."), TargetExpression(text = "will → would / can → could", meaning = "Modals step back too.", note = "“I'll help” → he'd help."), TargetExpression(text = "asked where/when/why + past", meaning = "Reported questions.", note = "No inversion, no do."), TargetExpression(text = "Rumour mode: People are saying…", meaning = "Report gossip loosely.", note = "…the office is closing. Really?")), situation = "You come back from a day off to a wall of office rumours: report who said what, and separate reliable reports from gossip.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Report: “I'm leaving the company.” (Tom, to you)", expected = listOf("Tom said he was leaving the company.", "Tom told me he was leaving the company."), focus = "is → was", watch = "“Tom said he is leaving” is possible in casual speech — the exam-safe form shifts to was."), PracticeQuestion(prompt = "Report: “We will announce it on Friday.” (the manager)", expected = listOf("The manager said they would announce it on Friday."), focus = "will → would", watch = "“said they will” — shift the modal too: would."), PracticeQuestion(prompt = "Report: “I can't find the file.” (Ana)", expected = listOf("Ana said she couldn't find the file.", "Ana told me she couldn't find the file."), focus = "can → could", watch = "Never “said me” — say (that) or told me."), PracticeQuestion(prompt = "Report the question: “Where do you work?”", expected = listOf("She asked where I worked."), focus = "reported question", watch = "No did, no inversion: “asked where did I work” is wrong."), PracticeQuestion(prompt = "Pass on gossip about the merger. (People are saying…)", expected = listOf("People are saying the merger is off.", "People are saying there's going to be a merger."), focus = "rumour mode", watch = "are saying keeps it vague and deniable."), PracticeQuestion(prompt = "Correct a rumour: “I thought you were leaving, but you're not.”", expected = listOf("I thought you were leaving, but you're still here.", "I thought you were leaving — obviously not!"), focus = "thought + shift", watch = "thought + was for the belief you had."))), exercises = listOf(Exercise(id = "en-foundations-change-reported-e1", kind = "choice", prompt = "She ___ she was tired.", options = listOf("said", "told", "says to", "spoke"), answers = listOf("said"), explain = "say (that) + clause; tell needs a person: told ME."), Exercise(id = "en-foundations-change-reported-e2", kind = "gap", prompt = "They said they ___ call later. (will → shift)", options = listOf(), answers = listOf("would", "'d"), explain = "will steps back to would."), Exercise(id = "en-foundations-change-reported-e3", kind = "order", prompt = "Report this question. (asked / I / where / she / lived)", options = listOf(), answers = listOf("She asked where I lived"), explain = "asked + question word + subject + past."), Exercise(id = "en-foundations-change-reported-e4", kind = "written", prompt = "Fix: “He said me he is busy.”", options = listOf(), answers = listOf("he told me he was busy", "he said he was busy"), explain = "said me doesn't exist; and is shifts to was.")), skills = listOf("grammar:reported-speech-basic", "grammar:past-simple-irregular", "function:tell-a-story", "vocab:work"), canDo = listOf("tell-a-story"), prerequisites = listOf("grammar:past-simple-irregular")),
    Lesson(id = "en-foundations-change-phrasals", title = "Phrasal verbs you already use", goal = "Master the ten everyday phrasal verbs that replace formal verbs in speech.", intro = LessonIntro(explanation = listOf("A phrasal verb = verb + particle with its own meaning: get up (leave the bed), give up (stop trying), look for (search). The particle changes everything.", "Separable or not: “turn it off” (separable — the pronoun goes in the middle, never at the end). “Look after the cat” (inseparable). Learn each verb's habit.", "Formal English often has a single-verb twin: find out = discover, put off = postpone. Speech prefers the phrasal; writing accepts both."), examples = listOf(ExampleLine(text = "I get up at six even on Sundays.", meaning = "leave the bed."), ExampleLine(text = "Don't give up now!", meaning = "stop trying."), ExampleLine(text = "I'm looking for my keys.", meaning = "searching."), ExampleLine(text = "Turn it off and back on again.", meaning = "Separable: turn the computer off."), ExampleLine(text = "Can you look after the cat this weekend?", meaning = "Inseparable: take care of."), ExampleLine(text = "I found out the truth yesterday.", meaning = "= discovered."))), expressions = listOf(TargetExpression(text = "get up", meaning = "Leave the bed.", note = "I got up late."), TargetExpression(text = "give up", meaning = "Stop trying.", note = "give up + -ing: give up smoking."), TargetExpression(text = "look for / look after", meaning = "Search / take care of.", note = "Different meanings, same verb."), TargetExpression(text = "turn on/off (separable)", meaning = "Pronoun in the middle.", note = "turn it on, never turn on it."), TargetExpression(text = "find out", meaning = "= discover.", note = "I'll find out and tell you."), TargetExpression(text = "put off = postpone", meaning = "Formal twin exists.", note = "They put off the meeting.")), situation = "A friend is moving house: phrasal verbs everywhere — get up early, pick up boxes, look after the dog, give up the sofa, turn off the lights.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Say what time you leave the bed on Mondays.", expected = listOf("I get up at <time> on Mondays."), focus = "get up", watch = "“I get me up” — no pronoun: I get up."), PracticeQuestion(prompt = "Encourage a friend who wants to quit the gym to continue.", expected = listOf("Don't give up!"), focus = "give up", watch = "give up alone works: no object needed."), PracticeQuestion(prompt = "Ask someone to take care of your dog this weekend.", expected = listOf("Can you look after my dog this weekend?"), focus = "look after", watch = "look after ≠ look for (search)."), PracticeQuestion(prompt = "The pronoun goes in the middle: the lights / turn off / them.", expected = listOf("Turn them off.", "Turn off the lights.", "Turn the lights off."), focus = "separable", watch = "“Turn off them” is wrong — pronouns sit inside."), PracticeQuestion(prompt = "Say you discovered the truth yesterday. (phrasal)", expected = listOf("I found out the truth yesterday."), focus = "find out", watch = "found out, not “found up” or “discovered out”."), PracticeQuestion(prompt = "Say the meeting was postponed. (phrasal)", expected = listOf("They put off the meeting.", "The meeting was put off."), focus = "put off", watch = "put off + thing; put the meeting off also works."))), exercises = listOf(Exercise(id = "en-foundations-change-phrasals-e1", kind = "choice", prompt = "Can you ___ ___ my plants while I'm away?", options = listOf("look after", "look for", "look up", "look at"), answers = listOf("look after"), explain = "look after = take care of; look for = search."), Exercise(id = "en-foundations-change-phrasals-e2", kind = "gap", prompt = "Turn ___ ___ before you leave. (the lights, pronoun)", options = listOf(), answers = listOf("them off", "it off"), explain = "Separable: the pronoun goes inside."), Exercise(id = "en-foundations-change-phrasals-e3", kind = "order", prompt = "Encourage your friend.", options = listOf(), answers = listOf("Don't give up now"), explain = "don't give up = keep trying."), Exercise(id = "en-foundations-change-phrasals-e4", kind = "written", prompt = "Phrasal twin: “They postponed the meeting.”", options = listOf(), answers = listOf("they put off the meeting", "they put the meeting off"), explain = "put off = postpone.")), skills = listOf("grammar:phrasal-verbs", "vocab:daily-routine", "function:talk-about-routines"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:present-simple"))))
}

object EnFoundationsTelling {
    val unit = CourseUnit(id = "en-foundations-telling", title = "Telling it well", subtitle = "Collocations, reactions, problems", level = "B1", themes = listOf(ConversationTheme("good-news-bad-news", "Good news, bad news", "React naturally", "arrow.up.arrow.down", "Course", "You swap news with a friend: some wonderful, some terrible — your reactions carry the conversation.", 0),
                ConversationTheme("the-broken-thing", "The broken thing", "Explain and fix", "wrench.and.screwdriver", "Course", "Something you rented is broken. Explain the problem clearly and agree on a solution.", 1)), lessons = listOf(    Lesson(id = "en-foundations-telling-collocations", title = "Collocations that carry you", goal = "Use the word pairs natives reach for: make a decision, have a break, pay attention.", intro = LessonIntro(explanation = listOf("Collocations are fixed friendships between words: make a decision (never do a decision), pay attention, take responsibility.", "Learn them as whole chunks: word-by-word assembly is how “do a mistake” happens — mistakes are made.", "When unsure, ask a native: “What's the usual verb here?” They hear the pair, not the rule."), examples = listOf(ExampleLine(text = "We need to make a decision today.", meaning = "make + decision."), ExampleLine(text = "Let's have a break.", meaning = "have + break/rest."), ExampleLine(text = "Pay attention to the deadline.", meaning = "pay + attention."), ExampleLine(text = "I made a mistake in the report.", meaning = "make + mistake."), ExampleLine(text = "She takes responsibility for the project.", meaning = "take + responsibility."))), expressions = listOf(TargetExpression(text = "make a decision / mistake", meaning = "The two makes.", note = "Never do a decision."), TargetExpression(text = "have a break / rest", meaning = "have + rest words.", note = "Let's have a break."), TargetExpression(text = "pay attention (to)", meaning = "Focus.", note = "…to the details."), TargetExpression(text = "take responsibility / a seat", meaning = "take pairs.", note = "take your time."), TargetExpression(text = "do someone a favour", meaning = "do + favour.", note = "Can you do me a favour?"), TargetExpression(text = "heavy traffic / light rain", meaning = "Adjective pairs.", note = "The traffic is heavy.")), situation = "You and a colleague polish an email together: swap the literal phrase