    val unit = CourseUnit(id = "en-foundations-media", title = "Media & argument", subtitle = "News, claims, debate", level = "B2", themes = listOf(ConversationTheme("editorial-meeting", "The editorial meeting", "What's the story?", "newspaper", "Course", "You pitch a story: what happened, why now, why anyone should care — in ninety seconds.", 0),
                ConversationTheme("letters-page", "The letters page", "Claim and counter", "envelope", "Course", "You respond to an opinion piece: concede a point, then dismantle it politely.", 1)), lessons = listOf(    Lesson(id = "en-foundations-media-news-language", title = "The language of news", goal = "Read and report news: passive reporting, headline grammar and attribution.", intro = LessonIntro(explanation = listOf("Headlines drop words: “Bridge reopened after repairs” = The bridge has been reopened. Learn to expand them.", "Attribution protects reporters: “It is believed that…”, “according to sources”. Nobody said it; it is said.", "The passive rules news because events matter more than doers: “Measures were announced” — by whom, later, maybe."), examples = listOf(ExampleLine(text = "Bridge reopened after repairs.", meaning = "A headline: expand to a full sentence."), ExampleLine(text = "It is believed that costs will fall.", meaning = "Attribution without a source."), ExampleLine(text = "Measures were announced on Tuesday.", meaning = "Event-focused passive."), ExampleLine(text = "The minister is thought to favour delays.", meaning = "is thought to + verb."), ExampleLine(text = "According to the report, numbers fell.", meaning = "according to = the source."))), expressions = listOf(TargetExpression(text = "… was/were + participle", meaning = "The reporting backbone.", note = "The road was closed."), TargetExpression(text = "It is said/believed that …", meaning = "Source-free attribution.", note = "It is believed that…"), TargetExpression(text = "is thought to + verb", meaning = "Report others' claims.", note = "He is thought to have left."), TargetExpression(text = "according to …", meaning = "Name the source.", note = "according to the report."), TargetExpression(text = "are expected to + verb", meaning = "Predictions from others.", note = "Talks are expected to continue."), TargetExpression(text = "Headline → sentence", meaning = "Expand dropped words.", note = "“Man rescues cat” = A man has rescued a cat.")), situation = "You brief a colleague on this morning's news: expand three headlines into full sentences and attribute every claim you can't verify.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Expand the headline: “Bridge reopened”.", expected = listOf("The bridge has been reopened."), focus = "headline → sentence", watch = "Add the dropped words: has been + participle."), PracticeQuestion(prompt = "Report unverified costs. (it / believe)", expected = listOf("It is believed that costs will fall."), focus = "attribution", watch = "It is believed protects the speaker."), PracticeQuestion(prompt = "Attribute a number to its source. (report)", expected = listOf("According to the report, sales fell by 10%."), focus = "according to", watch = "according to names the source."), PracticeQuestion(prompt = "Report what people think about the minister. (thought / delay)", expected = listOf("The minister is thought to favour delays."), focus = "is thought to", watch = "is thought to have + participle for past acts."), PracticeQuestion(prompt = "Report expected talks.", expected = listOf("Talks are expected to continue."), focus = "are expected to", watch = "Passive prediction: nobody predicts, it is expected."))), exercises = listOf(Exercise(id = "en-foundations-media-news-language-e1", kind = "choice", prompt = "The road ___ closed since March.", options = listOf("has been", "is been", "was being", "had being"), answers = listOf("has been"), explain = "Present perfect passive: has been closed."), Exercise(id = "en-foundations-media-news-language-e2", kind = "gap", prompt = "It is ___ that costs will fall. (believe)", options = listOf(), answers = listOf("believed"), explain = "It is believed that…"), Exercise(id = "en-foundations-media-news-language-e3", kind = "order", prompt = "Expand the headline.", options = listOf(), answers = listOf("The bridge has been reopened after repairs"), explain = "has been + participle + detail."), Exercise(id = "en-foundations-media-news-language-e4", kind = "written", prompt = "Attribute the fall to the report.", options = listOf(), answers = listOf("according to the report sales fell", "sales fell according to the report"), explain = "according to + source.")), skills = listOf("grammar:passive-intro", "grammar:present-perfect", "grammar:relative-clauses", "function:express-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:past-simple-regular")),
    Lesson(id = "en-foundations-media-opinion-pieces", title = "Opinion pieces", goal = "Build a written argument: claim, support, concession, rebuttal.", intro = LessonIntro(explanation = listOf("The four-move structure: claim (“Remote work is here to stay”), support (evidence), concession (“Admittedly, not every job…”), rebuttal (“But the trend is clear”).", "Concession words buy credibility: admittedly, granted, while it's true that… — you look fair before you disagree.", "Endings circle back: “For all its flaws, the evidence points one way.” Repeat the claim, changed by everything before it."), examples = listOf(ExampleLine(text = "Remote work is here to stay.", meaning = "The claim — short and bare."), ExampleLine(text = "Studies show a 13% productivity rise.", meaning = "Support with numbers."), ExampleLine(text = "Admittedly, not every job can be remote.", meaning = "The concession."), ExampleLine(text = "But the trend is unmistakable.", meaning = "The rebuttal."), ExampleLine(text = "For all its flaws, the evidence points one way.", meaning = "The circular close."))), expressions = listOf(TargetExpression(text = "The claim: …", meaning = "State it bare.", note = "One sentence, no hedging yet."), TargetExpression(text = "Support: studies show / data suggests", meaning = "Bring evidence.", note = "Numbers beat adjectives."), TargetExpression(text = "Admittedly, … / Granted, …", meaning = "Concede fairly.", note = "Fairness buys trust."), TargetExpression(text = "But / However, …", meaning = "Rebut.", note = "But the core point stands."), TargetExpression(text = "For all its flaws, …", meaning = "Circle back.", note = "The claim, transformed.")), situation = "You draft a 120-word opinion piece on four-day weeks: claim, one piece of support, one fair concession, one rebuttal, one close.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "State your claim about four-day weeks. (here to stay)", expected = listOf("Four-day weeks are here to stay."), focus = "the claim", watch = "Short. Bare. Debatable."), PracticeQuestion(prompt = "Add one number as support.", expected = listOf("Trials report a 13% productivity rise."), focus = "support", watch = "A number does the arguing for you."), PracticeQuestion(prompt = "Concede fairly: not every job. (admittedly)", expected = listOf("Admittedly, not every job can be done remotely."), focus = "the concession", watch = "admittedly + the strongest counter-case."), PracticeQuestion(prompt = "Rebut the concession. (but / trend)", expected = listOf("But the trend is unmistakable."), focus = "the rebuttal", watch = "However also works — but is punchier."), PracticeQuestion(prompt = "Close by circling back.", expected = listOf("For all its flaws, the evidence points one way."), focus = "the close", watch = "The claim returns, stronger."))), exercises = listOf(Exercise(id = "en-foundations-media-opinion-pieces-e1", kind = "choice", prompt = "___ not every job can be remote, the trend is clear.", options = listOf("Admittedly", "Because", "So", "Unless"), answers = listOf("Admittedly"), explain = "admittedly concedes before rebutting."), Exercise(id = "en-foundations-media-opinion-pieces-e2", kind = "gap", prompt = "Studies ___ a 13% productivity rise. (show)", options = listOf(), answers = listOf("show"), explain = "studies show + number."), Exercise(id = "en-foundations-media-opinion-pieces-e3", kind = "order", prompt = "The circular close.", options = listOf(), answers = listOf("For all its flaws the evidence points one way"), explain = "for all its flaws + claim."), Exercise(id = "en-foundations-media-opinion-pieces-e4", kind = "written", prompt = "State your claim about four-day weeks.", options = listOf(), answers = listOf("four-day weeks are here to stay", "four day weeks are here to stay"), explain = "Short, bare, debatable.")), skills = listOf("writing:argument", "grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "vocab:work"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:first-conditional"))))
