object EnFoundationsNuance {
    val unit = CourseUnit(id = "en-foundations-nuance", title = "Nuance & register", subtitle = "Say it the better way", level = "C1", themes = listOf(ConversationTheme("formal-swap", "The register swap", "Same idea, different room", "arrow.triangle.swap", "Course", "You rephrase the same message for different audiences: a friend, a client, a complaint, a keynote.", 0),
                ConversationTheme("idiom-lab", "The idiom lab", "Sound natural", "text.bubble", "Course", "You upgrade literal sentences with natural chunks and idioms — carefully, one at a time.", 1)), lessons = listOf(    Lesson(id = "en-foundations-nuance-register", title = "Register: formal vs informal", goal = "Rephrase the same message for different audiences and levels of formality.", intro = LessonIntro(explanation = listOf("Informal leans on phrasal verbs and contractions: “We'll set up a call.” Formal prefers single verbs: “We will arrange a call.”", "Requests climb the ladder of politeness: “Send it” → “Can you send it?” → “Could you send it?” → “I would be grateful if you could send it.”", "Written formality also changes vocabulary: get → receive, help → assistance, but → however, kids → children."), examples = listOf(ExampleLine(text = "We'll set up a call tomorrow. (informal)", meaning = "Phrasal + contraction."), ExampleLine(text = "We will arrange a call tomorrow. (formal)", meaning = "Single verb, no contraction."), ExampleLine(text = "Can you send the invoice?", meaning = "Neutral request."), ExampleLine(text = "I would be grateful if you could send the invoice.", meaning = "Formal request."), ExampleLine(text = "Sorry, that doesn't work for me. (informal)", meaning = "Soft refusal."), ExampleLine(text = "Unfortunately, that arrangement is not feasible. (formal)", meaning = "Formal refusal."))), expressions = listOf(TargetExpression(text = "set up vs arrange", meaning = "Phrasal informal, single verb formal.", note = "Same meaning, different room."), TargetExpression(text = "I would be grateful if you could …", meaning = "The formal request.", note = "Emails, clients, institutions."), TargetExpression(text = "Unfortunately, … is not feasible.", meaning = "The formal no.", note = "feasible = possible/viable."), TargetExpression(text = "get → receive", meaning = "Upgrade everyday verbs.", note = "We received your message."), TargetExpression(text = "kids → children", meaning = "Register-sensitive nouns.", note = "Formal writing avoids kids."), TargetExpression(text = "Sorry about that → I apologise for the inconvenience.", meaning = "Apology ladder.", note = "Match the damage.")), situation = "One message, three rooms: say the same cancellation to a friend, then to a client, then in a formal complaint — and feel the register move.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Say informally that you'll organise a call.", expected = listOf("I'll set up a call.", "We'll set up a call."), focus = "informal register", watch = "Phrasal verbs + contractions are the informal markers."), PracticeQuestion(prompt = "Now say it formally. (arrange)", expected = listOf("We will arrange a call.", "I will arrange a call."), focus = "formal register", watch = "Single verb, no contraction."), PracticeQuestion(prompt = "Make this formal: “Can you send the report?”", expected = listOf("I would be grateful if you could send the report.", "Could you please send the report?"), focus = "request ladder", watch = "would be grateful is the top rung for email."), PracticeQuestion(prompt = "Refuse formally: the arrangement doesn't work.", expected = listOf("Unfortunately, that arrangement is not feasible.", "Unfortunately, we are unable to accept the arrangement."), focus = "formal refusal", watch = "Formal refusals start with unfortunately and avoid contractions."), PracticeQuestion(prompt = "Make this formal: “Sorry about the delay.”", expected = listOf("I apologise for the delay.", "Please accept my apologies for the delay."), focus = "apology ladder", watch = "Match formality to the damage."), PracticeQuestion(prompt = "Spot the register: “We received your message” vs “We got your message”.", expected = listOf("we received your message is formal", "we got your message is informal"), focus = "get vs receive", watch = "Same meaning; receive belongs to formal writing."))), exercises = listOf(Exercise(id = "en-