    Lesson(id = "en-foundations-nuance-chunks", title = "Natural chunks", goal = "Replace literal sentences with natural chunks and idioms — precisely, not decoratively.", intro = LessonIntro(explanation = listOf("Chunks are ready-made phrases native speakers reach for: “It depends.” “That makes sense.” “As far as I know…” “I'm not sure about that.”", "Idioms carry culture and risk: “It's a grey area” is safe and useful; rare or dated idioms can sound costume-y. One per conversation is plenty.", "Upgrading literal speech: “I don't decide yet” → “I'm still on the fence.” The chunk must match the meaning exactly."), examples = listOf(ExampleLine(text = "It depends on the weather.", meaning = "The universal answer chunk."), ExampleLine(text = "That makes sense.", meaning = "Accepting an explanation."), ExampleLine(text = "As far as I know, the flight is on time.", meaning = "Limited certainty."), ExampleLine(text = "I'm still on the fence.", meaning = "Undecided."), ExampleLine(text = "It's a bit of a grey area.", meaning = "Not clearly one thing or the other."), ExampleLine(text = "Let's play it by ear.", meaning = "Decide as things happen."))), expressions = listOf(TargetExpression(text = "It depends.", meaning = "Conditional answer.", note = "…on + factor: on the price."), TargetExpression(text = "That makes sense.", meaning = "Understanding confirmed.", note = "Never “it has sense”."), TargetExpression(text = "As far as I know, …", meaning = "Soften a claim.", note = "Knowledge may be incomplete."), TargetExpression(text = "I'm on the fence.", meaning = "No decision yet.", note = "Sitting between two options."), TargetExpression(text = "a grey area", meaning = "Unclear rules or meaning.", note = "The law here is a grey area."), TargetExpression(text = "play it by ear", meaning = "Improvise the plan.", note = "No fixed script.")), situation = "You coach a colleague before a difficult meeting: swap their literal lines for natural chunks — and decide which idioms to avoid.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Answer naturally when asked if remote work is better.", expected = listOf("It depends.", "It depends on the job."), focus = "it depends", watch = "“It depends of” — English takes on."), PracticeQuestion(prompt = "Confirm you understood the explanation.", expected = listOf("That makes sense."), focus = "makes sense", watch = "Never “it has sense” — the chunk is makes sense."), PracticeQuestion(prompt = "Soften a claim about tomorrow's schedule.", expected = listOf("As far as I know, it's free.", "As far as I know, the schedule hasn't changed."), focus = "limited certainty", watch = "The chunk admits your knowledge might be incomplete."), PracticeQuestion(prompt = "Say you haven't decided between the two offers.", expected = listOf("I'm still on the fence."), focus = "undecided", watch = "The fence sits between two options — that's the image."), PracticeQuestion(prompt = "Say the rule is unclear. (idiom)", expected = listOf("It's a bit of a grey area.", "It's a grey area."), focus = "grey area", watch = "grey (BrE) or gray (AmE) — both fine."), PracticeQuestion(prompt = "Say you'll decide as things happen. (idiom)", expected = listOf("Let's play it by ear.", "We'll play it by ear."), focus = "play it by ear", watch = "ear, not year — it comes from music."))), exercises = listOf(Exercise(id = "en-foundations-nuance-chunks-e1", kind = "choice", prompt = "Which chunk means “no decision yet”?", options = listOf("I'm on the fence.", "It's a grey area.", "It depends.", "That makes sense."), answers = listOf("I'm on the fence."), explain = "On the fence = between two options, undecided."), Exercise(id = "en-foundations-nuance-chunks-e2", kind = "gap", prompt = "That ___ sense — thanks for explaining.", options = listOf(), answers = listOf("makes"), explain = "makes sense, never has sense."), Exercise(id = "en-foundations-nuance-chunks-e3", kind = "order", prompt = "Soften your claim about the flight.", options = listOf(), answers = listOf("As far as I know the flight is on time"), explain = "as far as I know + the claim."), Exercise(id = "en-foundations-nuance-chunks-e4", kind = "written", prompt = "Fix: “It depends of the price.”", options = listOf(), answers = listOf("it depends on the price"), explain = "depend on + factor.")), skills = listOf("vocab:social-expressions", "function:express-opinion", "speaking:sustained-conversation", "writing:argument"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:connectors")),
    Lesson(id = "en-foundations-nuance-hedging", title = "Hedging & precision", goal = "Fine-tune opinions: soften, intensify and qualify like a confident speaker.", intro = LessonIntro(explanation = listOf("Hedging protects accuracy: “tends to”, “to some extent”, “arguably”, “in most cases”. Strong claims need strong evidence — otherwise hedge.", "Intensifiers scale: slightly < rather < considerably < far. “Far more efficient” is stronger than “slightly more efficient”.", "Precision beats intensity: “a threefold increase” > “a lot more”. Numbers, examples and scope (“in this case”) make opinions defensible."), examples = listOf(ExampleLine(text = "This approach tends to work better.", meaning = "A hedged claim."), ExampleLine(text = "To some extent, I agree.", meaning = "Partial agreement."), ExampleLine(text = "Arguably, it's the best option on the table.", meaning = "Opinion with room."), ExampleLine(text = "The new version is far more stable.", meaning = "A strong, clear difference."), ExampleLine(text = "Costs fell by roughly a third.", meaning = "Precision with a number."), ExampleLine(text = "In this specific case, I'd wait.", meaning = "Scope limiting."))), expressions = listOf(TargetExpression(text = "tends to + verb", meaning = "General pattern, not law.", note = "Prices tend to rise in summer."), TargetExpression(text = "to some extent / to a degree", meaning = "Partial truth.", note = "Agreement with reservations."), TargetExpression(text = "arguably", meaning = "Defensible opinion.", note = "Arguably the best paella in town."), TargetExpression(text = "slightly / rather / considerably / far", meaning = "The intensity scale.", note = "far > considerably > rather > slightly."), TargetExpression(text = "by roughly a third", meaning = "Approximate precision.", note = "roughly, about, approximately."), TargetExpression(text = "in this specific case", meaning = "Limit the scope.", note = "No universal claims.")), situation = "You present an opinion to a skeptical audience: claim, hedge, quantify and limit scope — then defend it once challenged.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Hedge a claim about remote productivity.", expected = listOf("Remote work tends to increase productivity.", "It tends to work better for focused tasks."), focus = "tends to", watch = "tends to + base verb softens the pattern without killing it."), PracticeQuestion(prompt = "Agree, but only partly.", expected = listOf("To some extent, I agree.", "I agree to a degree."), focus = "partial agreement", watch = "The quantifier keeps the disagreement alive."), PracticeQuestion(prompt = "Give a defensible superlative opinion about a restaurant.", expected = listOf("Arguably, it's the best ramen in the city."), focus = "arguably", watch = "arguably signals: I can defend this."), PracticeQuestion(prompt = "Rank the intensifiers: slightly / far / rather. (weakest to strongest)", expected = listOf("slightly, rather, far"), focus = "intensity scale", watch = "slightly < rather < considerably < far."), PracticeQuestion(prompt = "Be precise about a cost drop: from 90 to 60. (roughly)", expected = listOf("Costs fell by roughly a third."), focus = "approximate numbers", watch = "roughly + fraction beats “a lot less”."), PracticeQuestion(prompt = "Limit your advice so it isn't universal.", expected = listOf("In this specific case, I'd wait.", "In this case, I'd wait before deciding."), focus = "scope", watch = "in this case protects the advice from other contexts."))), exercises = listOf(Exercise(id = "en-foundations-nuance-hedging-e1", kind = "choice", prompt = "Which claim is the most hedged?", options = listOf("It tends to work better.", "It always works.", "It works.", "It never fails."), answers = listOf("It tends to work better."), explain = "tends to is the hedged pattern claim."), Exercise(id = "en-foundations-nuance-hedging-e2", kind = "gap", prompt = "The new engine is ___ more efficient. (strongest intensifier)", options = listOf(), answers = listOf("far", "considerably"), explain = "far (or considerably) is stronger than slightly."), Exercise(id = "en-foundations-nuance-hedging-e3", kind = "order", prompt = "Give a partial agreement.", options = listOf(), answers = listOf("To some extent I agree"), explain = "to some extent + I agree."), Exercise(id = "en-foundations-nuance-hedging-e4", kind = "written", prompt = "Fix: “It depends of the context.”", options = listOf(), answers = listOf("it depends on the context"), explain = "depend on — the preposition is on.")), skills = listOf("grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "writing:argument"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:connectors")),
    Lesson(id = "en-foundations-nuance-academic", title = "The academic voice", goal = "State positions in academic and professional registers: impersonal, evidenced, measured.", intro = LessonIntro(explanation = listOf("The academic voice removes the “I”: “This paper argues that…”, “The data suggests…”, “It has been observed that…”. The claim carries the sentence, not the person.", "Evidence verbs scale certainty: demonstrate > suggest > indicate > appear to. Choose the verb that matches the strength of your data.", "Structure is visible: “First… Second… Taken together, these findings…” — the reader should always know where they are."), examples = listOf(ExampleLine(text = "This paper argues that hybrid models outperform either extreme.", meaning = "The thesis sentence."), ExampleLine(text = "The data suggests a modest effect.", meaning = "suggests = careful."), ExampleLine(text = "The results demonstrate a clear correlation.", meaning = "demonstrate = strong evidence."), ExampleLine(text = "It has been observed that remote teams innovate differently.", meaning = "Impersonal passive reporting."), ExampleLine(text = "Taken together, these findings point to a structural cause.", meaning = "Synthesis marker."), ExampleLine(text = "Further research is needed to confirm the effect.", meaning = "The classic closing hedge."))), expressions = listOf(TargetExpression(text = "This paper/chapter argues that …", meaning = "State the thesis.", note = "argue = defend a position."), TargetExpression(text = "The data suggests / demonstrates …", meaning = "Certainty scaled to evidence.", note = "Choose the honest verb."), TargetExpression(text = "It has been observed that …", meaning = "Impersonal reporting.", note = "Passive keeps the I out."), TargetExpression(text = "Taken together, …", meaning = "Synthesise several points.", note = "Ends the middle, opens the close."), TargetExpression(text = "Further research is needed …", meaning = "The honest limit.", note = "Every study ends here."), TargetExpression(text = "with respect to / regarding", meaning = "Formal topic shifts.", note = "Regarding costs, the picture differs.")), situation = "You present a controversial finding to a skeptical panel: thesis, evidence verbs that match your data, visible structure and an honest limit.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "State your thesis formally. (hybrid models outperform)", expected = listOf("This paper argues that hybrid models outperform either extreme."), focus = "thesis", watch = "argues that + full clause — the position, not the topic."), PracticeQuestion(prompt = "Your evidence is moderate. Choose the verb. (the data / a modest effect)", expected = listOf("The data suggests a modest effect."), focus = "scaled verbs", watch = "demonstrates would overclaim; suggests is honest."), PracticeQuestion(prompt = "Your evidence is strong. Choose the verb. (clear correlation)", expected = listOf("The results demonstrate a clear correlation."), focus = "scaled verbs", watch = "With strong data, demonstrates is the honest choice."), PracticeQuestion(prompt = "Report an observation without saying who observed it.", expected = listOf("It has been observed that remote teams innovate differently."), focus = "impersonal passive", watch = "It + has been + participle keeps the voice out."), PracticeQuestion(prompt = "Synthesise two findings into one conclusion.", expected = listOf("Taken together, these findings point to a structural cause."), focus = "synthesis", watch = "Taken together announces the synthesis."), PracticeQuestion(prompt = "Close with the honest limit of the study.", expected = listOf("Further research is needed to confirm the effect."), focus = "the limit", watch = "Every credible study admits its edge."))), exercises = listOf(Exercise(id = "en-foundations-nuance-academic-e1", kind = "choice", prompt = "The data ___ a modest effect. (moderate evidence)", options = listOf("suggests", "demonstrates", "proves", "ignores"), answers = listOf("suggests"), explain = "Moderate evidence takes suggests, not demonstrates."), Exercise(id = "en-foundations-nuance-academic-e2", kind = "gap", prompt = "It has ___ observed that remote teams innovate differently.", options = listOf(), answers = listOf("been"), explain = "Impersonal passive: has been + participle."), Exercise(id = "en-foundations-nuance-academic-e3", kind = "order", prompt = "State the thesis.", options = listOf(), answers = listOf("This paper argues that hybrid models outperform either extreme"), explain = "This paper argues that + claim."), Exercise(id = "en-foundations-nuance-academic-e4", kind = "written", prompt = "Close the study honestly.", options = listOf(), answers = listOf("further research is needed to confirm the effect", "further research is needed"), explain = "The classic honest close.")), skills = listOf("writing:argument", "grammar:passive-intro", "function:express-opinion", "function:talk-about-work", "grammar:connectors"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:passive-intro", "grammar:connectors")),
    Lesson(id = "en-foundations-nuance-presenting", title = "Presenting with confidence", goal = "Signpost a talk, land key points and handle questions without losing your footing.", intro = LessonIntro(explanation = listOf("Signposts keep audiences aboard: “I'll start with…”, “That brings me to…”, “So, to sum up…”. Say where you are; nobody resents a map.", "Land key points with a pause and a restatement: “The one thing to remember is this.” Silence sells importance.", "Hard questions get a frame: “That's exactly the point — my answer is twofold.” Buying structure, not stalling."), examples = listOf(ExampleLine(text = "I'll start with why this matters.", meaning = "The opening signpost."), ExampleLine(text = "That brings me to the results.", meaning = "The transition."), ExampleLine(text = "The one thing to remember is this.", meaning = "Point-landing phrase."), ExampleLine(text = "So, to sum up: three findings, one conclusion.", meaning = "The summary signpost."), ExampleLine(text = "That's exactly the point — and my answer is twofold.", meaning = "Handling the hard question."))), expressions = listOf(TargetExpression(text = "I'll start with …", meaning = "Open the map.", note = "I'll start with the problem."), TargetExpression(text = "That brings me to …", meaning = "Transition.", note = "…to the second point."), TargetExpression(text = "The one thing to remember is …", meaning = "Land the point.", note = "Then pause. Let it sit."), TargetExpression(text = "So, to sum up …", meaning = "Signal the close.", note = "Repeat the three parts."), TargetExpression(text = "That's exactly the point.", meaning = "Own the hard question.", note = "Then answer in two parts."), TargetExpression(text = "I'm glad you asked that.", meaning = "Buy a second, kindly.", note = "Use sparingly — overdone it's a cliché.")), situation = "You present a small project to a skeptical room: signpost the three parts, land one key sentence and survive two tough questions.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open your talk by announcing the first part.", expected = listOf("I'll start with why this matters.", "I'll start with the problem."), focus = "opening signpost", watch = "I'll start with + noun: “I'll start with to explain” is wrong."), PracticeQuestion(prompt = "Move from findings to recommendations.", expected = listOf("That brings me to my recommendations."), focus = "transition", watch = "brings me to + noun: the signpost is the map."), PracticeQuestion(prompt = "Land your single key message.", expected = listOf("The one thing to remember is this: focus beats time."), focus = "landing", watch = "Say it, then stop talking. The pause is the emphasis."), PracticeQuestion(prompt = "Signal you are closing.", expected = listOf("So, to sum up: three findings, one conclusion."), focus = "the close", watch = "to sum up + the structure you promised at the start."), PracticeQuestion(prompt = "Handle a hostile question confidently.", expected = listOf("That's exactly the point — and my answer is twofold."), focus = "hard questions", watch = "Own the question, then give structure: first… second…"))), exercises = listOf(Exercise(id = "en-foundations-nuance-presenting-e1", kind = "gap", prompt = "I'll ___ ___ why this matters. (2 words)", options = listOf(), answers = listOf("start with"), explain = "I'll start with + noun."), Exercise(id = "en-foundations-nuance-presenting-e2", kind = "gap", prompt = "That ___ me to my second point.", options = listOf(), answers = listOf("brings"), explain = "That brings me to…"), Exercise(id = "en-foundations-nuance-presenting-e3", kind = "order", prompt = "Signal the summary.", options = listOf(), answers = listOf("So to sum up three findings one conclusion"), explain = "So, to sum up: …"), Exercise(id = "en-foundations-nuance-presenting-e4", kind = "written", prompt = "Own a hostile question before answering.", options = listOf(), answers = listOf("thats exactly the point", "that is exactly the point"), explain = "That's exactly the point — then structure.")), skills = listOf("function:talk-about-work", "speaking:sustained-conversation", "grammar:connectors", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:connectors"))))
}

object EnWorkU1 {
    val unit = CourseUnit(id = "en-work-u1", title = "The working day", subtitle = "Meetings, emails, interviews", level = "B1", themes = listOf(ConversationTheme("monday-standup", "Monday stand-up", "Report your week", "clock", "Course", "You report progress in a stand-up: what you did, what you're doing, what's blocked.", 0),
                ConversationTheme("interview-roleplay", "The interview rehearsal", "Sell your experience", "person.badge.key", "Course", "A job interview rehearsal: present yourself, describe projects and answer the hard questions.", 1)), lessons = listOf(    Lesson(id = "en-work-u1-meetings", title = "In meetings", goal = "Report progress, ask for clarification and disagree politely in a meeting.", intro = LessonIntro(explanation = listOf("Structure beats improvisation: “Last week I finished X. This week I'm working on Y. I'm blocked on Z.”", "Clarify before you guess: “Sorry, could you clarify that?” “Just to make sure I understand…”", "Disagree with data, not people: “I see it slightly differently — the numbers show…”"), examples = listOf(ExampleLine(text = "Last week I finished the report.", meaning = "Done work, past simple."), ExampleLine(text = "This week I'm working on the budget.", meaning = "Current work, continuous."), ExampleLine(text = "I'm blocked on the approvals.", meaning = "Say what stops you."), ExampleLine(text = "Sorry, could you clarify that?", meaning = "Ask before assuming."), ExampleLine(text = "Just to make sure I understand: we ship on Friday?", meaning = "Confirm decisions."), ExampleLine(text = "I see it slightly differently — the data shows a drop.", meaning = "Data-based disagreement."))), expressions = listOf(TargetExpression(text = "Last week I finished …", meaning = "Report completed work.", note = "Past simple for done things."), TargetExpression(text = "This week I'm working on …", meaning = "Report current work.", note = "Continuous for in progress."), TargetExpression(text = "I'm blocked on …", meaning = "Name the blocker.", note = "Blocked on + thing, not person."), TargetExpression(text = "Could you clarify …?", meaning = "Ask precisely.", note = "Clarify + the specific point."), TargetExpression(text = "Just to make sure I understand, …", meaning = "Confirm decisions.", note = "Repeat the decision back."), TargetExpression(text = "I see it slightly differently.", meaning = "Soft disagreement.", note = "Then bring your data.")), situation = "Monday stand-up: report what you finished, what you're on and what's blocked; clarify one point and politely disagree with a plan once.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Report one thing you finished last week.", expected = listOf("Last week I finished <task>."), focus = "past simple reporting", watch = "“Last week I finish” — done work takes past simple."), PracticeQuestion(prompt = "Report what you're doing this week.", expected = listOf("This week I'm working on <task>."), focus = "current work", watch = "“This week I work on” sounds like a routine — use the continuous."), PracticeQuestion(prompt = "Tell the team what is blocking you. (approvals)", expected = listOf("I'm blocked on the approvals."), focus = "blockers", watch = "“I'm blocked by the approvals” also works; “I block on” doesn't."), PracticeQuestion(prompt = "Ask for clarification about the deadline.", expected = listOf("Sorry, could you clarify the deadline?", "Could you clarify when the deadline is?"), focus = "clarifying", watch = "Clarify + the thing: the deadline, the owner, the scope."), PracticeQuestion(prompt = "Confirm a decision you half-heard. (ship on Friday)", expected = listOf("Just to make sure I understand: we ship on Friday?"), focus = "confirming", watch = "Repeat the decision back as a question."), PracticeQuestion(prompt = "Disagree with a plan, politely, with data.", expected = listOf("I see it slightly differently — the data shows a drop.", "I see your point; however, the numbers say otherwise."), focus = "soft disagreement", watch = "Data first, tone soft: no “you're wrong”."))), exercises = listOf(Exercise(id = "en-work-u1-meetings-e1", kind = "choice", prompt = "Last week I ___ the report.", options = listOf("finished", "finish", "am finishing", "was finishing"), answers = listOf("finished"), explain = "Last week + past s