    Lesson(id = "en-work-u1-emails", title = "Professional emails", goal = "Write short professional emails: request, confirm and follow up.", intro = LessonIntro(explanation = listOf("Email skeleton: greeting → purpose in line one → details → clear ask → sign-off. “Hi Marta, I'm writing about… Could you…? Thanks, Dan.”", "Requests: “Could you send… by Wednesday?” Deadlines make asks actionable. Follow-ups stay light: “Just following up on my email below.”", "Register: no contractions is safer in formal mail; “I would be grateful if…” is the formal ask."), examples = listOf(ExampleLine(text = "I'm writing about Thursday's meeting.", meaning = "Purpose in line one."), ExampleLine(text = "Could you send the figures by Wednesday?", meaning = "Request + deadline."), ExampleLine(text = "Please find the report attached.", meaning = "The attachment line."), ExampleLine(text = "Just following up on my email below.", meaning = "Light follow-up."), ExampleLine(text = "I would be grateful if you could confirm.", meaning = "Formal ask."), ExampleLine(text = "Best regards, Daniel", meaning = "Safe sign-off."))), expressions = listOf(TargetExpression(text = "I'm writing about / to ask about …", meaning = "Open with purpose.", note = "No weather talk in work mail."), TargetExpression(text = "Could you … by <day>?", meaning = "Request + deadline.", note = "A deadline is kindness."), TargetExpression(text = "Please find … attached.", meaning = "Point at the file.", note = "attached, not annexed."), TargetExpression(text = "Just following up on …", meaning = "Nudge without nagging.", note = "Light tone, clear reference."), TargetExpression(text = "I would be grateful if you could …", meaning = "The formal ask.", note = "Clients, institutions, bosses' bosses."), TargetExpression(text = "Best regards / Kind regards", meaning = "Safe sign-offs.", note = "Cheers is for friends only.")), situation = "You need numbers from a busy colleague: write the request, set a deadline, and then follow up two days later — politely.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open an email about the quarterly figures.", expected = listOf("I'm writing about the quarterly figures."), focus = "purpose first", watch = "Line one states the topic — no “I hope you are well” padding needed."), PracticeQuestion(prompt = "Ask for the figures with a deadline. (Wednesday)", expected = listOf("Could you send the figures by Wednesday?"), focus = "request + deadline", watch = "by + day: “until Wednesday” is different — by is the limit."), PracticeQuestion(prompt = "Point to the report you attached.", expected = listOf("Please find the report attached."), focus = "attachment line", watch = "The fixed phrase is find … attached."), PracticeQuestion(prompt = "Follow up on an unanswered email, lightly.", expected = listOf("Just following up on my email below."), focus = "follow-up", watch = "“Why didn't you answer?” is never the opening."), PracticeQuestion(prompt = "Make the formal version of the ask. (confirm attendance)", expected = listOf("I would be grateful if you could confirm your attendance."), focus = "formal register", watch = "would be grateful + if you could."), PracticeQuestion(prompt = "Choose a safe sign-off for a client.", expected = listOf("Best regards.", "Kind regards."), focus = "sign-off", watch = "Cheers and hugs stay with friends."))), exercises = listOf(Exercise(id = "en-work-u1-emails-e1", kind = "choice", prompt = "I'm writing ___ the invoice.", options = listOf("about", "of", "for see", "on see"), answers = listOf("about"), explain = "I'm writing about + topic."), Exercise(id = "en-work-u1-emails-e2", kind = "gap", prompt = "Could you send it ___ Friday? (deadline)", options = listOf(), answers = listOf("by"), explain = "by Friday = not later than Friday."), Exercise(id = "en-work-u1-emails-e3", kind = "order", prompt = "The attachment line.", options = listOf(), answers = listOf("Please find the report attached"), explain = "find + file + attached."), Exercise(id = "en-work-u1-emails-e4", kind = "written", prompt = "Formal ask: confirm attendance.", options = listOf(), answers = listOf("i would be grateful if you could confirm your attendance", "i would be grateful if you could confirm attendance"), explain = "I would be grateful if you could…")), skills = listOf("writing:email", "function:make-requests", "grammar:modal-should", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:modal-should")),
    Lesson(id = "en-work-u1-interviews", title = "Job interviews", goal = "Present yourself, describe achievements and handle hard questions in an interview.", intro = LessonIntro(explanation = listOf("The achievement formula: situation → action → result. “The team was behind (S). I rebuilt the schedule (A) and we shipped on time (R).”", "Weakness questions want honesty plus growth: “I used to over-plan; now I timebox decisions.”", "Buy time politely: “That's a good question — let me think for a second.” Silence feels longer to you than to them."), examples = listOf(ExampleLine(text = "I've led a team of five for three years.", meaning = "Present perfect for ongoing relevance."), ExampleLine(text = "The project was behind, so I rebuilt the schedule.", meaning = "Situation + action."), ExampleLine(text = "As a result, we shipped two weeks early.", meaning = "Result with a number if possible."), ExampleLine(text = "I used to over-plan; now I timebox decisions.", meaning = "Weakness + growth."), ExampleLine(text = "That's a good question — let me think for a second.", meaning = "Buying time."), ExampleLine(text = "I'm particularly proud of the migration project.", meaning = "Selective pride."))), expressions = listOf(TargetExpression(text = "I've + participle + for/since", meaning = "Experience that continues.", note = "I've worked here since 2021."), TargetExpression(text = "The situation was …, so I …", meaning = "Story spine.", note = "S-A-R: situation, action, result."), TargetExpression(text = "As a result, …", meaning = "Land the outcome.", note = "Numbers beat adjectives."), TargetExpression(text = "I used to …; now I …", meaning = "Weakness + growth.", note = "Never say “I'm a perfectionist”."), TargetExpression(text = "Let me think for a second.", meaning = "Buy time.", note = "Then answer in structure."), TargetExpression(text = "I'm particularly proud of …", meaning = "Choose your highlight.", note = "One story, told well.")), situation = "Interview rehearsal: introduce your experience, tell one achievement with S-A-R, answer the weakness question and negotiate next steps.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Describe your current role and how long you've had it.", expected = listOf("I've worked as a <role> for <time>.", "I've been a <role> since <year>."), focus = "present perfect", watch = "for + period, since + point."), PracticeQuestion(prompt = "Tell one achievement as a story. (situation → action → result)", expected = listOf("The project was behind, so I rebuilt the schedule, and as a result we shipped on time."), focus = "S-A-R", watch = "The result is the point — land it with as a result."), PracticeQuestion(prompt = "Answer the weakness question honestly with growth.", expected = listOf("I used to over-plan; now I timebox decisions."), focus = "weakness + growth", watch = "used to for the old habit, now for the fix."), PracticeQuestion(prompt = "Buy time on a hard question.", expected = listOf("That's a good question — let me think for a second."), focus = "buying time", watch = "Then structure the answer: point, example, close."), PracticeQuestion(prompt = "Explain why you want this job. (growth + contribution)", expected = listOf("I want to grow into <area>, and I believe I can contribute <strength>."), focus = "two-sided motivation", watch = "What you gain AND what you bring."), PracticeQuestion(prompt = "Close the interview politely.", expected = listOf("Thank you — I look forward to hearing from you."), focus = "closing", watch = "look forward to + -ing."))), exercises = listOf(Exercise(id = "en-work-u1-interviews-e1", kind = "choice", prompt = "I've worked here ___ 2021.", options = listOf("since", "for", "from", "during"), answers = listOf("since"), explain = "since + point in time; for + period."), Exercise(id = "en-work-u1-interviews-e2", kind = "gap", prompt = "___ a result, we shipped two weeks early.", options = listOf(), answers = listOf("as"), explain = "As a result + outcome."), Exercise(id = "en-work-u1-interviews-e3", kind = "order", prompt = "Buy time politely.", options = listOf(), answers = listOf("That's a good question let me think for a second"), explain = "The buying-time formula."), Exercise(id = "en-work-u1-interviews-e4", kind = "written", prompt = "Weakness + growth: over-plan → timebox.", options = listOf(), answers = listOf("i used to over-plan now i timebox decisions", "i used to over plan now i timebox decisions"), explain = "used to (old) + now (new).")), skills = listOf("grammar:present-perfect", "grammar:used-to", "function:talk-about-work", "speaking:justify-opinion", "function:introduce-yourself"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:present-perfect", "grammar:used-to"))))
