object EsFoundationsU1 {
    val unit = CourseUnit(id = "es-foundations-u1", title = "First sentences", subtitle = "Say who you are", level = "A1", themes = listOf(ConversationTheme("lang-exchange", "Language-exchange café", "Meet and greet", "person.2", "Course", "You are at a friendly language-exchange café in Madrid. Meet the learner, exchange names, countries and jobs using the verb ser.", 0),
                ConversationTheme("introductions", "Nice to meet you", "Start somewhere small", "hand.wave", "Connection", "Meet the learner for the first time. Learn their interests through natural introductions.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u1-ser", title = "The verb “ser”", goal = "Introduce yourself and say who people are with soy, eres, es, somos, son.", intro = LessonIntro(explanation = listOf("Every Spanish sentence needs a subject and a verb. The most important verb for saying who you are is “ser”.", "One verb, five present forms: yo soy, tú eres, él/ella es, nosotros somos, ellos/ellas son. With “you” formal, use usted es.", "Use ser for identity and origin: “Soy Ana”, “Soy de España”, “Es profesora”. These facts do not change, so ser is the verb."), examples = listOf(ExampleLine(text = "Soy Ana. Soy de España.", meaning = "Your name and country."), ExampleLine(text = "Eres mi mejor amigo.", meaning = "A close bond with someone."), ExampleLine(text = "Ella es profesora.", meaning = "Someone's profession."), ExampleLine(text = "Somos muy felices hoy.", meaning = "A feeling that defines right now."), ExampleLine(text = "El café es cercano a la estación.", meaning = "Where a place is."), ExampleLine(text = "Ellos son de Madrid.", meaning = "Someone's origin."))), expressions = listOf(TargetExpression(text = "Soy …", meaning = "Introduce yourself.", note = "With your name, job or feeling: Soy Ana. Soy profesora."), TargetExpression(text = "Soy de …", meaning = "Say where you come from.", note = "Never “Soy España” — the de is obligatory: Soy de España."), TargetExpression(text = "¿Eres …?", meaning = "Ask about the other person.", note = "¿Eres estudiante? ¿Eres de aquí?"), TargetExpression(text = "Sí, lo soy. / No, no lo soy.", meaning = "Short answers to an ¿Eres…? question.", note = "Repeat the verb through lo: never just “Sí”."), TargetExpression(text = "Es …", meaning = "Say what someone else is.", note = "Es profesor — the article is often dropped with jobs: Es médico."), TargetExpression(text = "Encantado de conocerte.", meaning = "The fixed phrase when you meet someone.", note = "Answer with Encantada if you are a woman, or Igualmente.")), situation = "You meet someone new at a friendly language-exchange café in Madrid. Introduce yourselves and ask simple questions with the verb ser.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "¡Hola! Soy Ana. ¿Cómo te llamas?", expected = listOf("Me llamo <name>.", "Soy <name>."), focus = "Me llamo / Soy", watch = "Answering only the name without the verb: accept it, then recast “Me llamo …”."), PracticeQuestion(prompt = "¿De dónde eres?", expected = listOf("Soy de <country>."), focus = "ser + de", watch = "“Soy España” — recast “Soy DE España”, stress de."), PracticeQuestion(prompt = "¿Eres estudiante?", expected = listOf("Sí, lo soy.", "No, no lo soy."), focus = "short answers with ser", watch = "“Sí estudiante” — the short answer needs the verb."), PracticeQuestion(prompt = "¿Cómo estás hoy?", expected = listOf("Estoy bien.", "Estoy cansado.", "Estoy feliz."), focus = "estar for feelings", watch = "“Soy cansado” — recast “Estoy cansado”: feelings take estar."), PracticeQuestion(prompt = "Tu ciudad, ¿es grande o pequeña?", expected = listOf("Es grande.", "Es pequeña.", "Mi ciudad es …"), focus = "es with things and places", watch = "“Mi ciudad grande” — recast “Mi ciudad ES grande”."), PracticeQuestion(prompt = "¡Ya somos amigos! ¿De dónde es tu familia?", expected = listOf("Es de <country>.", "Mi familia es de <country>."), focus = "es for a group's origin", watch = "“Mi familia de …” — recast with es."))), exercises = listOf(Exercise(id = "es-foundations-u1-ser-e1", kind = "choice", prompt = "Ella ___ profesora.", options = listOf("es", "eres", "soy", "somos"), answers = listOf("es"), explain = "With él/ella/usted, ser becomes es."), Exercise(id = "es-foundations-u1-ser-e2", kind = "gap", prompt = "Nosotros ___ de Madrid.", options = listOf(), answers = listOf("somos"), explain = "With nosotros, ser is siempre somos."), Exercise(id = "es-foundations-u1-ser-e3", kind = "order", prompt = "Say where you are from.", options = listOf(), answers = listOf("Soy de España"), explain = "Soy + de + country: Soy de España."), Exercise(id = "es-foundations-u1-ser-e4", kind = "written", prompt = "Introduce yourself in one sentence: say your name.", options = listOf(), answers = listOf("Me llamo <name>", "Soy <name>"), explain = "Me llamo Ana / Soy Ana — the verb is never dropped.")), skills = listOf("grammar:verb-be", "grammar:subject-pronouns", "function:describe-people", "speaking:short-answer"), canDo = listOf("describe-people"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "es-foundations-u1-questions", title = "Questions & negatives", goal = "Ask yes/no questions and say what is not true, with ¿Eres…? and no soy.", intro = LessonIntro(explanation = listOf("To ask a yes/no question in Spanish, keep the word order and just add the question marks — your voice goes up at the end: “¿Eres Ana?”", "Question words carry an accent: ¿Qué? ¿Dónde? ¿Cómo? They go first: “¿De dónde eres?”", "To say something is not true, put no before the verb: “No soy Ana”, “No somos amigos”. In answers, no… twice is normal: “No, no lo soy”."), examples = listOf(ExampleLine(text = "¿Eres tú profesora?", meaning = "A yes/no question with eres."), ExampleLine(text = "No soy de Madrid.", meaning = "A negative with soy."), ExampleLine(text = "¿De dónde eres?", meaning = "Question word + eres."), ExampleLine(text = "Él no es mi hermano.", meaning = "A negative about another person."), ExampleLine(text = "¿Sois vosotros vecinos?", meaning = "Asking a group."), ExampleLine(text = "¿Qué es esto?", meaning = "What is this?"))), expressions = listOf(TargetExpression(text = "¿Eres …?", meaning = "Ask a yes/no question.", note = "Same order as the statement, just the marks and rising tone."), TargetExpression(text = "No soy …", meaning = "Say what is not true about you.", note = "No always goes before the verb: No soy de Sevilla."), TargetExpression(text = "¿De dónde eres?", meaning = "Ask where someone is from.", note = "De dónde, two words with accents."), TargetExpression(text = "No es …", meaning = "Say what someone else is not.", note = "Él no es mi jefe."), TargetExpression(text = "¿Verdad?", meaning = "Tag a statement to check it.", note = "Es tu casa, ¿verdad?"), TargetExpression(text = "Claro.", meaning = "The natural yes in talk.", note = "Also: Por supuesto.")), situation = "You chat with a new neighbour in the lift in Madrid. Ask simple yes/no questions and say what is and isn't true for you.", practice = LessonPractice(questions = listOf(Practic