stOf("No soy de Valencia"), explain = "no + soy: No soy de Valencia.")), skills = listOf("grammar:verb-be", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "es-foundations-u1-introduce", title = "Introducing yourself", goal = "Give a complete self-introduction: name, country, nationality and job.", intro = LessonIntro(explanation = listOf("A full Spanish introduction has four pieces: your name, your city or country, your nationality and your job.", "For the name: “Me llamo Ana” (I call myself Ana) or simply “Soy Ana”. For origin: “Soy de España”. Nationalities are lower-case: “soy española”.", "Jobs with ser drop the article: “Soy profesora”, not “Soy una profesora”. Add “Mucho gusto” at the end to close politely."), examples = listOf(ExampleLine(text = "Me llamo Ana. Mucho gusto.", meaning = "Your name plus a polite close."), ExampleLine(text = "Soy de Sevilla, del sur de España.", meaning = "City inside country."), ExampleLine(text = "Soy española, de Andalucía.", meaning = "Nationality plus region."), ExampleLine(text = "Soy enfermera en un hospital.", meaning = "Job plus workplace."), ExampleLine(text = "Tengo veinticinco años.", meaning = "Your age — with tener, not ser."), ExampleLine(text = "Encantada. ¿Y tú?", meaning = "Close and bounce the question back."))), expressions = listOf(TargetExpression(text = "Me llamo …", meaning = "Give your name.", note = "Literally “I call myself”. Also: Mi nombre es …"), TargetExpression(text = "Soy + nationality", meaning = "Say your nationality.", note = "española, francesa, alemana — nationality is lower-case in Spanish."), TargetExpression(text = "Soy de …", meaning = "Say your city or country.", note = "Soy de Sevilla; Soy de España."), TargetExpression(text = "Trabajo en …", meaning = "Say where you work.", note = "Trabajo en un hospital / en una escuela."), TargetExpression(text = "Mucho gusto.", meaning = "Polite close when you meet someone.", note = "Answer: Igualmente."), TargetExpression(text = "¿Y tú?", meaning = "Bounce the question back.", note = "—Soy de Madrid. ¿Y tú?")), situation = "Your first day at a language school in Madrid. Present yourself completely to the class: name, city, nationality and job.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "¿Cómo te llamas?", expected = listOf("Me llamo <name>.", "Soy <name>."), focus = "name formulas", watch = "Both are fine; recast the shorter one as Me llamo for variety."), PracticeQuestion(prompt = "¿De dónde eres?", expected = listOf("Soy de <country>."), focus = "origin", watch = "Never drop de: Soy DE <country>."), PracticeQuestion(prompt = "¿Cuál es tu nacionalidad?", expected = listOf("Soy <nationality>."), focus = "nationality with ser", watch = "Lower-case: soy española, not Española."), PracticeQuestion(prompt = "¿A qué te dedicas?", expected = listOf("Soy <job>.", "Trabajo en <place>."), focus = "jobs without article", watch = "“Soy una profesora” — recast dropping the article."), PracticeQuestion(prompt = "¿Y dónde vives?", expected = listOf("Vivo en <city>."), focus = "vivo en", watch = "“Vivo a Madrid” — recast with en."), PracticeQuestion(prompt = "¡Encantado! ¿Y tú, de qué trabajas?", expected = listOf("Soy <job>.", "Trabajo de <job>."), focus = "bounce back and answer", watch = "Accept Soy de <job>? No — recast: Trabajo DE/Soy <job>."))), exercises = listOf(Exercise(id = "es-foundations-u1-introduce-e1", kind = "choice", prompt = "___ Ana. Mucho gusto.", options = listOf("Me llamo", "Me llamo de", "Llamo", "Estoy"), answers = listOf("Me llamo"), explain = "Me llamo + name: one piece, no de."), Exercise(id = "es-foundations-u1-introduce-e2", kind = "gap", prompt = "Soy ___ Italia. (nationality)", options = listOf(), answers = listOf("italiana"), explain = "Nationality is lower-case: italiana, italiano."), Exercise(id = "es-foundations-u1-introduce-e3", kind = "order", prompt = "Say your name and city.", options = listOf(), answers = listOf("Soy Ana y soy de Madrid"), explain = "Two soy pieces, both with their verb."), Exercise(id = "es-foundations-u1-introduce-e4", kind = "written", prompt = "Give your complete introduction: name and country.", options = listOf(), answers = listOf("Me llamo <name> y soy de <country>", "Soy <name> y soy de <country>", "Me llamo <name>, soy de <country>"), explain = "Name + origin, each with its verb.")), skills = listOf("grammar:verb-be", "function:introduce-yourself", "vocab:introductions", "pron:word-stress"), canDo = listOf("introduce-yourself"))))
