ice(questions = listOf(PracticeQuestion(prompt = "Tu es d'ici ?", expected = listOf("Oui, je suis d'ici.", "Non, je ne suis pas d'ici."), focus = "short answers", watch = "One-word “Oui” — recast with the verb: Oui, je suis d'ici."), PracticeQuestion(prompt = "Tu es professeur ou étudiant ?", expected = listOf("Je suis professeur.", "Je suis étudiant.", "Je suis professeure."), focus = "choice with être", watch = "Accept either; note the article stays dropped."), PracticeQuestion(prompt = "Ta famille est grande ?", expected = listOf("Oui, elle est grande.", "Non, elle n'est pas grande."), focus = "est in questions about others", watch = "“Elle n'est pas grande” — n' before est."), PracticeQuestion(prompt = "Tu es de où, toi ?", expected = listOf("Je suis de <country>.", "Je viens de <country>."), focus = "où + es", watch = "“Je suis à France” — recast with de: Je suis DE France."), PracticeQuestion(prompt = "Dis-moi quelque chose que tu n'es pas.", expected = listOf("Je ne suis pas <job>.", "Je ne suis pas de <country>."), focus = "negation ne…pas", watch = "Both parts needed: ne before, pas after."), PracticeQuestion(prompt = "On est amis maintenant ?", expected = listOf("Oui, on est amis.", "Bien sûr, on est amis."), focus = "on est", watch = "“On sommes” doesn't exist — on always takes est."))), exercises = listOf(Exercise(id = "fr-foundations-u1-questions-e1", kind = "choice", prompt = "¿ ___ tu de Marseille ?", options = listOf("Es", "Est", "Suis", "Êtes"), answers = listOf("Es"), explain = "With tu, the question starts with Es: Tu es de… ?"), Exercise(id = "fr-foundations-u1-questions-e2", kind = "gap", prompt = "Elle ___ pas ma sœur.", options = listOf(), answers = listOf("n'est"), explain = "ne + est → n'est pas: n' before the vowel."), Exercise(id = "fr-foundations-u1-questions-e3", kind = "order", prompt = "Say you are not from Nantes.", options = listOf(), answers = listOf("Je ne suis pas de Nantes"), explain = "ne + suis + pas wraps the verb."), Exercise